INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('007---everything-or-nothing-jrising-sun', 'GAMEBOYADVANCE', '007 - Everything or Nothing (J)(Rising Sun)', '2004', 'Action', 'EA Games', '1', 'Action Adventure', 'Third-person tactical shooting and gadget-based stealth action.', 'Complete espionage missions to stop a global nanotech threat.', 'Experience the ultimate Bond adventure with high-tech gadgets and intense action.', 'James Bond 007 Everything or Nothing for GBA brings cinematic spy action to your handheld. Master stealth mechanics, use iconic gadgets, and engage in high-stakes combat to thwart a global conspiracy in this top-tier action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---asterix-and-obelix-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Asterix and Obelix (E)(Rising Sun)', '2004', 'Platform', 'Atari', '1', 'Platformer', 'Classic side-scrolling platformer with two playable characters.', 'Navigate through Roman-occupied lands to reach the end of each level.', 'Join Asterix and Obelix in this fun-filled, Roman-bashing platforming adventure.', 'Relive the classic comic book adventures in Asterix and Obelix 2-in-1. Featuring vibrant 2D graphics and challenging platforming levels, players must use the unique strengths of both Gauls to defeat Caesar’s armies and explore ancient Europe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---barbie-groovy-games-&-secret-agent-barbie-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Barbie Groovy Games & Secret Agent Barbie (E)(Supplex)', '2004', 'Mini-Games', 'WayForward Technologies', '1', 'Casual', 'Collection of mini-games and isometric stealth-platforming levels.', 'Win various casual games and complete secret missions as a top agent.', 'A versatile combo featuring fashion-forward puzzles and exciting spy missions.', 'The Barbie Groovy Games & Secret Agent Barbie bundle offers diverse gameplay for fans. From casual puzzles and board games to stealthy platforming missions, this collection provides hours of entertainment with Barbie in her most iconic roles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---barenbruder-&-disney-prinzessinen-gindependent', 'GAMEBOYADVANCE', '2 in 1 - Barenbruder & Disney Prinzessinen (G)(Independent)', '2005', 'Party', 'Independent', '1', 'Casual', 'Animal-themed adventure and magical platforming levels.', 'Help Koda and Kenai on their journey and fulfill princess quests.', 'A magical double pack featuring forest adventures and royal Disney stories.', 'Explore nature and royalty with the Barenbruder (Brother Bear) & Disney Princess pack. This German-language edition features engaging 2D platforming, puzzle-solving elements, and beloved characters from the Disney universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---brother-bear-&-disney-princess-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Brother Bear & Disney Princess (E)(Independent)', '2005', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platformer and puzzle-adventure gameplay.', 'Guide the bears through the wild and complete various princess tales.', 'Embark on a double journey through the Great North and enchanted kingdoms.', 'Disney''s Brother Bear & Disney Princess 2-in-1 brings two hits to one cartridge. Navigate treacherous terrain as Kenai and Koda, then switch to magical princess stories filled with puzzles and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---cabelas-sportsmans-pack-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Cabela''s Sportsman''s Pack (U)(Sir VG)', '2005', 'Sports', 'Cabela''s', '1', 'Sports', 'First-person hunting simulation and outdoor management.', 'Hunt specific game animals and manage equipment in the wilderness.', 'The ultimate outdoor challenge for hunting enthusiasts on the go.', 'Cabela''s Sportsman''s Pack offers a realistic hunting simulation for GBA. Track big game across various environments, upgrade your gear, and master the art of the hunt in this comprehensive collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---cartoon-network---block-party-&-cartoon-network---speedway-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Cartoon Network - Block Party & Cartoon Network - Speedway (U)(Trashman)', '2004', 'Party', 'Cartoon Network', '4', 'Party', 'Isometric mini-games and top-down arcade racing.', 'Win party challenges and finish first in high-speed cartoon races.', 'Double the fun with Cartoon Network’s best mini-games and racing circuits.', 'Experience Cartoon Network Block Party & Speedway in one pack. Compete in board-game style challenges with your favorite characters, then jump into the driver''s seat for fast-paced racing action across iconic CN locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---cartoon-network---block-party-&-speedway-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Cartoon Network - Block Party & Speedway (E)(sUppLeX)', '2004', 'Party', 'Cartoon Network', '4', 'Party', 'Isometric mini-games and top-down arcade racing.', 'Win party challenges and finish first in high-speed cartoon races.', 'Double the fun with Cartoon Network’s best mini-games and racing circuits.', 'Experience Cartoon Network Block Party & Speedway in one pack. Compete in board-game style challenges with your favorite characters, then jump into the driver''s seat for fast-paced racing action across iconic CN locations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---castlevania-double-pack-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Castlevania Double Pack (E)(Rising Sun)', '2006', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action-RPG (Metroidvania) with exploration.', 'Explore Dracula''s castle and defeat the Lord of Darkness.', 'Two legendary Castlevania masterpieces: Aria of Sorrow and Harmony of Dissonance.', 'The Castlevania Double Pack is a must-have for GBA owners. Featuring two of the best Metroidvania titles ever made, players will explore vast gothic maps, collect souls, and battle iconic monsters in these deep, atmospheric action-RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---castlevania-double-pack-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Castlevania Double Pack (U)(Trashman)', '2006', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action-RPG (Metroidvania) with exploration.', 'Explore Dracula''s castle and defeat the Lord of Darkness.', 'Two legendary Castlevania masterpieces: Aria of Sorrow and Harmony of Dissonance.', 'The Castlevania Double Pack is a must-have for GBA owners. Featuring two of the best Metroidvania titles ever made, players will explore vast gothic maps, collect souls, and battle iconic monsters in these deep, atmospheric action-RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---columns-&-chu-chu-rocket-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Columns & Chu Chu Rocket (E)(Rising Sun)', '2003', 'Puzzle', 'Sega', '2', 'Puzzle', 'Falling-block puzzle and strategy-puzzle action.', 'Clear gems and guide ChuChus to their rockets while avoiding cats.', 'Two addictive SEGA puzzle classics in one portable package.', 'Master the grid with Columns & Chu Chu Rocket. This SEGA bundle brings endless puzzle variety, from the match-three strategy of Columns to the chaotic, fast-paced pathfinding challenges of Chu Chu Rocket.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---crash-&-spyro-super-pack-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Crash & Spyro Super Pack (U)(Sir VG)', '2005', 'Platform', 'Vicarious Visions', '1', 'Platformer', '3D-style platforming and collection-based adventure.', 'Save the worlds from the combined threats of Neo Cortex and Ripto.', 'Two legendary platforming heroes unite in one incredible GBA super pack.', 'The Crash & Spyro Super Pack for GBA delivers the best of both worlds. Run, jump, and spin through vibrant levels as Crash, then take to the skies as Spyro the dragon in this high-value handheld collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---crash-bandicoot-2---n-tranced-&-crash-nitro-kart-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Crash Bandicoot 2 - N-Tranced & Crash Nitro Kart (U)(Trashman)', '2005', 'Action', 'Vicarious Visions', '1', 'Action Racing', '2D platforming and high-speed kart racing action.', 'Defeat N. Tranced and win the intergalactic racing tournament.', 'A massive dose of marsupial madness with platforming and racing.', 'Crash Bandicoot 2: N-Tranced & Crash Nitro Kart offers two distinct gameplay styles. Tackle challenging levels to save your friends, then hit the tracks for competitive racing action in this essential GBA bundle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---crash-bandicoot-purple---riptos-rampage-&-spyro-orange---the-cortex-conspiracy-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Crash Bandicoot Purple - Ripto''s Rampage & Spyro Orange - The Cortex Conspiracy (U)(Independent)', '2005', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Crossover platforming and mini-game challenges.', 'Stop the villainous alliance between Dr. Cortex and Ripto.', 'Crash and Spyro join forces in a unique crossover adventure.', 'Crash Bandicoot Purple & Spyro Orange bring the two icons together. Navigate through diverse mini-games and platforming segments as you swap between worlds to defeat a villainous alliance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---disney-princess-&-the-lion-king-esir-vg', 'GAMEBOYADVANCE', '2 in 1 - Disney Princess & The Lion King (E)(Sir VG)', '2004', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platforming and adventure tasks.', 'Complete royal quests and reclaim the Pride Lands as Simba.', 'A royal collection featuring the best of Disney’s Princesses and The Lion King.', 'Join your favorite characters in the Disney Princess & The Lion King bundle. Experience the pride of Africa through Simba’s eyes and explore enchanted castles in various princess stories, blending classic platforming with magical Disney storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---disney-principesse-&-il-re-leone-iindependent', 'GAMEBOYADVANCE', '2 in 1 - Disney Principesse & Il Re Leone (I)(Independent)', '2004', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platforming and adventure tasks.', 'Complete royal quests and reclaim the Pride Lands as Simba.', 'A royal collection featuring the best of Disney’s Princesses and The Lion King.', 'Join your favorite characters in the Disney Princess & The Lion King bundle. Experience the pride of Africa through Simba’s eyes and explore enchanted castles in various princess stories, blending classic platforming with magical Disney storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---disney-sportpack-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Disney Sportpack (E)(Rising Sun)', '2004', 'Sports', 'Disney Interactive', '4', 'Sports', 'Compilation of various arcade-style sports mini-games.', 'Compete in themed sporting events and achieve high scores.', 'Get active with your favorite Disney characters in this sports collection.', 'The Disney Sportpack for GBA delivers a variety of sports-themed challenges. Play as Mickey and friends in scaled-down versions of popular sports, offering accessible gameplay and charming animations for sports fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---dora-the-explorer---pirate-pigs-treasure-&-super-star-adventures-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Dora the Explorer - Pirate Pig''s Treasure & Super Star Adventures (U)(Sir VG)', '2004', 'Adventure', 'Griptonite Games', '1', 'Adventure', 'Educational adventure and exploration platformer.', 'Find the Pirate Pig''s treasure and help Dora on her adventures.', 'Learn and play with Dora the Explorer in these two friendly adventures.', 'Dora the Explorer: Pirate Pig''s Treasure & Super Star Adventures is designed for younger players. It features simple puzzles, educational elements, and vibrant colors that bring the hit Nickelodeon show to life on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---dragon-ball-z---buus-fury-&-dragon-ball-gt---transformation-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Dragon Ball Z - Buu''s Fury & Dragon Ball GT - Transformation (U)(Independent)', '2004', 'RPG', 'TOSE', '1', 'JRPG', 'Action-RPG with combat and top-down beat ''em up elements.', 'Defeat Kid Buu and survive the quest for the Black Star Dragon Balls.', 'Experience the epic conclusion of Z and the start of GT in one pack.', 'Dragon Ball Z: Buu''s Fury & DBGT: Transformation brings the ultimate Saiyan experience. Level up your heroes, unleash powerful energy blasts, and fight through the most iconic battles of the Dragon Ball saga in these deep action titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---dragon-ball-z---the-legacy-of-goku-i-&-ii-urising-sun', 'GAMEBOYADVANCE', '2 in 1 - Dragon Ball Z - The Legacy of Goku I & II (U)(Rising Sun)', '2004', 'RPG', 'Webfoot Technologies', '1', 'JRPG', 'Action-RPG with exploration and real-time combat.', 'Relive the Saiyan, Namek, and Android sagas of the DBZ series.', 'The complete early DBZ story arc across two massive RPG adventures.', 'The Dragon Ball Z: Legacy of Goku I & II bundle is the definitive way to play the Z-story. Explore vast maps, complete quests, and evolve your powers from a young Goku to a Super Saiyan in these fan-favorite portable RPGs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---el-rey-leon-y-disney-princesas-sindependent', 'GAMEBOYADVANCE', '2 in 1 - El Rey Leon Y Disney Princesas (S)(Independent)', '2005', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platforming and adventure tasks.', 'Complete royal quests and reclaim the Pride Lands as Simba.', 'A royal collection featuring the best of Disney’s Princesses and The Lion King.', 'Join your favorite characters in the Disney Princess & The Lion King bundle. Experience the pride of Africa through Simba’s eyes and explore enchanted castles in various princess stories, blending classic platforming with magical Disney storytelling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---findet-nemo-&-das-abenteuer-geht-weiter-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Findet Nemo & Das Abenteuer Geht Weiter (E)(Independent)', '2003', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Underwater side-scrolling adventure and puzzle-platforming.', 'Find Nemo and navigate the dangers of the ocean and the city.', 'Two underwater adventures featuring Nemo, Dory, and the tank gang.', 'Finding Nemo & Finding Nemo: The Continuing Adventures lets you relive the Pixar magic. Navigate through coral reefs, dodge sharks, and solve puzzles to bring Nemo home in these visually impressive aquatic platformers.');
