INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---hot-wheels---velocity-x-&-hot-wheels---world-race-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Hot Wheels - Velocity X & Hot Wheels - World Race (U)(Trashman)', '2003', 'Racing', 'Vicarious Visions', '1', 'Arcade Racing', 'High-speed arcade racing and vehicular combat.', 'Win futuristic races and complete stunts to save the world.', 'Two high-octane Hot Wheels racing games in one explosive collection.', 'Experience the thrill of Hot Wheels: Velocity X & World Race. Drive iconic die-cast cars through gravity-defying tracks, engage in combat racing, and master stunt maneuvers in this ultimate GBA racing compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---hot-wheels-stunt-track-challenge-&-hot-wheels-world-race-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Hot Wheels Stunt Track Challenge & Hot Wheels World Race (U)(Sir VG)', '2003', 'Racing', 'Vicarious Visions', '1', 'Arcade Racing', 'Stunt-based racing and competitive world circuit driving.', 'Master extreme stunts and finish first in the World Race tournament.', 'Perform death-defying stunts and race for glory in this Hot Wheels pack.', 'Hot Wheels Stunt Track Challenge & World Race brings the excitement of the toy line to life. Compete in stunt competitions to earn points and race across interdimensional tracks in a quest for speed and precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---hugo-bukkazoom-&-hugo-&-the-evil-mirror-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Hugo Bukkazoom & Hugo & The Evil Mirror (E)(Rising Sun)', '2003', 'Action', 'Ite Media', '1', 'Action Adventure', 'Kart racing and 2D action platforming.', 'Win the Bukkazoom cup and rescue friends from the magic mirror.', 'Join Hugo the Troll in both a fast-paced racer and a magical adventure.', 'Hugo Bukkazoom & The Evil Mirror 2-in-1 offers variety for GBA players. Enjoy chaotic kart racing across wild environments and then dive into a classic side-scrolling platformer to defeat the forces of evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---insect-monster-&-suchai-labyrinth-jindependent', 'GAMEBOYADVANCE', '2 in 1 - Insect Monster & Suchai Labyrinth (J)(Independent)', '2004', 'Puzzle', 'Independent', '1', 'Puzzle', 'Strategy and puzzle-solving gameplay.', 'Conquer the insect kingdom and navigate through complex labyrinths.', 'A unique Japanese double pack featuring strategy and maze puzzles.', 'Insect Monster & Suchai Labyrinth offers a deep challenge for puzzle and strategy fans. Navigate through intricate mazes and manage your insect units to dominate the board in this classic import collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---kisekae-wanko-ex-&-puzzle-rainbow-magic-2-jindependent', 'GAMEBOYADVANCE', '2 in 1 - Kisekae Wanko Ex & Puzzle Rainbow Magic 2 (J)(Independent)', '2005', 'Puzzle', 'Independent', '1', 'Puzzle', 'Virtual pet simulation and match-three puzzle action.', 'Dress up adorable puppies and clear colorful magic puzzles.', 'A cute and colorful Japanese collection of pet care and puzzles.', 'Kisekae Wanko Ex & Puzzle Rainbow Magic 2 is perfect for fans of "kawaii" gaming. Care for your virtual puppies with various outfits and test your skills in fast-paced, vibrant puzzle levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---koda-fratello-orso-&-disney-principesse-iindependent', 'GAMEBOYADVANCE', '2 in 1 - Koda Fratello Orso & Disney Principesse (I)(Independent)', '2004', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling platformer and puzzle-adventure gameplay.', 'Guide the bears through the wild and complete various princess tales.', 'Embark on a double journey through the Great North and enchanted kingdoms.', 'Koda Fratello Orso & Disney Principesse brings the magic of Disney to GBA. This Italian-language edition features the heartwarming adventure of Brother Bear alongside the enchanted worlds of the Disney Princesses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---looney-tunes-double-pack---acme-antics-&-dizzy-driving-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Looney Tunes Double Pack - Acme Antics & Dizzy Driving (E)(Rising Sun)', '2003', 'Platform', 'Virgin Interactive', '1', 'Platformer', 'Isometric action and 2D kart racing.', 'Outsmart enemies in Acme adventures and win Looney Tunes races.', 'Double the laughs with classic Looney Tunes action and racing.', 'Looney Tunes Double Pack: Acme Antics & Dizzy Driving features your favorite cartoon characters. Tackle tricky isometric levels with Bugs Bunny and then jump into the driver''s seat for a wacky racing experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---looney-tunes-double-pack-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Looney Tunes Double Pack (U)(Sir VG)', '2003', 'Platform', 'Virgin Interactive', '1', 'Platformer', 'Isometric action and 2D kart racing.', 'Outsmart enemies in Acme adventures and win Looney Tunes races.', 'Double the laughs with classic Looney Tunes action and racing.', 'Looney Tunes Double Pack for GBA features iconic characters in two distinct modes. Experience the slapstick humor of Acme-themed missions and the high-speed fun of Dizzy Driving in one cart.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---madagascar-&-shrek-2-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Madagascar & Shrek 2 (E)(Independent)', '2005', 'Platform', 'DreamWorks', '1', 'Platformer', 'Side-scrolling platformer and 3D-style action adventure.', 'Help the zoo crew reach Africa and save Far Far Away with Shrek.', 'Relive the movie magic with Madagascar and Shrek 2 adventures.', 'Madagascar & Shrek 2 2-in-1 brings DreamWorks'' biggest hits to GBA. Navigate through platforming levels as Alex and Marty, then switch to Shrek’s swamp for an ogre-sized adventure filled with puzzles and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---madagascar-&-shrek-2-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Madagascar & Shrek 2 (U)(Independent)', '2005', 'Platform', 'DreamWorks', '1', 'Platformer', 'Side-scrolling platformer and 3D-style action adventure.', 'Help the zoo crew reach Africa and save Far Far Away with Shrek.', 'Relive the movie magic with Madagascar and Shrek 2 adventures.', 'Madagascar & Shrek 2 2-in-1 brings DreamWorks'' biggest hits to GBA. Navigate through platforming levels as Alex and Marty, then switch to Shrek’s swamp for an ogre-sized adventure filled with puzzles and combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---madagascar-operation-penguin-&-shrek-2-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Madagascar Operation Penguin & Shrek 2 (U)(Sir VG)', '2005', 'Platform', 'DreamWorks', '1', 'Platformer', 'Stealth-based platforming and 3D-style action adventure.', 'Complete penguin missions and fulfill Shrek''s fairytale quest.', 'Join the Madagascar penguins and Shrek in this action-packed duo.', 'Madagascar Operation Penguin & Shrek 2 offers a unique mix of stealth and platforming. Control the elite penguin squad on a secret mission and then join Shrek and Donkey on a journey to meet the King and Queen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---marble-madness-&-klax-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Marble Madness & Klax (E)(sUppLeX)', '2002', 'Arcade', 'Atari', '1', 'Arcade', 'Physics-based marble navigation and tile-matching puzzles.', 'Guide the marble to the exit and stack falling tiles to clear levels.', 'Two legendary Atari arcade classics in one addictive package.', 'Marble Madness & Klax brings retro arcade perfection to GBA. Master the precision-based physics of the marble runs and the fast-paced strategy of Klax’s tile-stacking gameplay in this timeless compilation.');
