INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---pferd-and-pony-mein-pferdehof-&-lass-uns-reiten-2-gsupplex', 'GAMEBOYADVANCE', '2 In 1 - Pferd And Pony (Mein Pferdehof) & Lass Uns Reiten 2 (G)(sUppLeX)', '2005', 'Simulation', 'Independent', '1', 'Life Simulation', 'Equestrian simulation and horse care management.', 'Manage a successful horse farm and win riding competitions.', 'The ultimate dream for horse lovers: farming and riding in one pack.', 'Pferd And Pony & Lass Uns Reiten 2 is a comprehensive horse simulation for GBA. Learn how to care for your horses, manage your stables, and compete in professional riding events in this detailed German title.');
