INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---prince-of-persia---the-sands-of-time-&-tomb-raider---the-prophecy-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Prince of Persia - The Sands of Time & Tomb Raider - The Prophecy (E)(Independent)', '2003', 'Action', 'Konami', '1', 'Action Adventure', '2D cinematic platforming and isometric action-adventure.', 'Use time-shifting powers and explore ruins as Lara Croft.', 'Two legendary adventure icons: Prince of Persia and Tomb Raider.', 'Prince of Persia: The Sands of Time & Tomb Raider: The Prophecy is the ultimate adventure bundle. Master wall-running and time manipulation with the Prince, then solve ancient mysteries as Lara Croft in this high-quality GBA pack.');
