INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-advance-&-sonic-battle-jsupplex', 'GAMEBOYADVANCE', '2 in 1 - Sonic Advance & Sonic Battle (J)(sUppLeX)', '2004', 'Action', 'Sonic Team', '1', 'Action Fighting', 'High-speed 2D platforming and 3D arena-based fighting.', 'Stop Dr. Eggman and emerge victorious in the ultimate Sonic brawl.', 'The best of Sonic: classic platforming speed and intense fighting action.', 'Sonic Advance & Sonic Battle (Japanese Version) combines the classic side-scrolling speed fans love with the deep, tactical arena combat of Sonic Battle, all on one portable GBA cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-advance-&-sonic-pinball-party-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Sonic Advance & Sonic Pinball Party (E)(Rising Sun)', '2003', 'Pinball', 'Sonic Team', '4', 'Pinball', 'High-speed 2D platforming and arcade pinball simulation.', 'Defeat Eggman and win the ultimate Sonic pinball tournament.', 'Speed through levels and hit the bumpers in this Sonic-themed pack.', 'Sonic Advance & Sonic Pinball Party offers a variety of SEGA action. Enjoy the high-speed platforming of the first Sonic Advance and then play through colorful pinball tables based on Sonic, NiGHTS, and Samba de Amigo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-advance-&-sonic-pinball-party-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Sonic Advance & Sonic Pinball Party (U)(Trashman)', '2003', 'Pinball', 'Sonic Team', '4', 'Pinball', 'High-speed 2D platforming and arcade pinball simulation.', 'Defeat Eggman and win the ultimate Sonic pinball tournament.', 'Speed through levels and hit the bumpers in this Sonic-themed pack.', 'Sonic Advance & Sonic Pinball Party for GBA provides endless replayability. Master the loops in the platforming stages and then achieve high scores on the most vibrant pinball tables ever seen on a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-battle-&-chuchu-rocket!-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Sonic Battle & ChuChu Rocket! (E)(Independent)', '2004', 'Action', 'Sonic Team', '1', 'Action Fighting', '3D arena-based fighting and strategy-puzzle action.', 'Master combat skills and guide mice to their rockets.', 'Intense Sonic brawling meets the strategic chaos of ChuChu Rocket.', 'Sonic Battle & ChuChu Rocket! is a unique SEGA compilation. Fight your way through the Sonic Battle story mode and then switch to the fast-paced puzzle action that made ChuChu Rocket a fan favorite.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-pinball-party-&-columns-crown-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Sonic Pinball Party & Columns Crown (E)(Independent)', '2003', 'Pinball', 'Sonic Team', '4', 'Pinball', 'Arcade pinball simulation and falling-block puzzle action.', 'Win the pinball cup and clear gems to protect the kingdom.', 'A perfect puzzle and arcade combo featuring Sonic and Columns.', 'Sonic Pinball Party & Columns Crown brings together two addictive genres. Play through festive pinball tables and then test your wits in the classic match-three strategy of Columns Crown.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-pinball-party-&-sonic-battle-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Sonic Pinball Party & Sonic Battle (E)(Rising Sun)', '2003', 'Pinball', 'Sonic Team', '4', 'Pinball', 'Arcade pinball simulation and 3D arena-based fighting.', 'Achieve pinball high scores and defeat rivals in arena combat.', 'Spin the ball with Sonic and fight for victory in arena battles.', 'Sonic Pinball Party & Sonic Battle 2-in-1 is packed with content. From the casino-style thrill of the pinball tables to the deep story and combat of Sonic Battle, this pack is a must-have for SEGA fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---sonic-pinball-party-&-sonic-battle-jsupplex', 'GAMEBOYADVANCE', '2 in 1 - Sonic Pinball Party & Sonic Battle (J)(sUppLeX)', '2003', 'Pinball', 'Sonic Team', '4', 'Pinball', 'Arcade pinball simulation and 3D arena-based fighting.', 'Achieve pinball high scores and defeat rivals in arena combat.', 'Spin the ball with Sonic and fight for victory in arena battles.', 'Sonic Pinball Party & Sonic Battle (Japanese Version) offers the same high-energy gameplay. Master the pinball physics and then dive into the isometric brawler that defines the Sonic fighting experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spider-man---mysterios-menace-&-x2---wolverines-revenge-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Spider-Man - Mysterio''s Menace & X2 - Wolverine''s Revenge (U)(Independent)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action and brawler gameplay.', 'Defeat Mysterio''s illusions and help Wolverine find his origins.', 'Two Marvel legends: Spider-Man and Wolverine in one action pack.', 'Spider-Man: Mysterio''s Menace & X2: Wolverine''s Revenge for GBA delivers comic book action. Swing through NYC to stop Mysterio and use Wolverine''s claws in visceral combat in this essential superhero duo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spider-man-&-spider-man-2-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Spider-Man & Spider-Man 2 (E)(Rising Sun)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action and movie-based adventure.', 'Stop the Green Goblin and defeat Doc Ock in NYC.', 'Swing into action with two Spidey adventures based on the films.', 'Spider-Man & Spider-Man 2 2-in-1 brings the movie trilogies to your GBA. Battle iconic villains, master web-slinging mechanics, and save the city in these two high-stakes action platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spider-man-&-spider-man-2-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Spider-Man & Spider-Man 2 (U)(Sir VG)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Side-scrolling action and movie-based adventure.', 'Stop the Green Goblin and defeat Doc Ock in NYC.', 'Swing into action with two Spidey adventures based on the films.', 'Spider-Man & Spider-Man 2 2-in-1 brings the movie trilogies to your GBA. Battle iconic villains, master web-slinging mechanics, and save the city in these two high-stakes action platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants---battle-for-bikini-bottom-&-fairly-oddparents---breakin-da-rules-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - SpongeBob Squarepants - Battle for Bikini Bottom & Fairly Oddparents - Breakin'' Da Rules (U)(Sir VG)', '2003', 'Platform', 'Heavy Iron Studios', '1', 'Platformer', 'Side-scrolling platforming and puzzle-adventure action.', 'Save Bikini Bottom and stop Vicky''s plan to ruin the holidays.', 'Join SpongeBob and Timmy Turner in this Nickelodeon double feature.', 'Battle for Bikini Bottom & Breakin'' Da Rules brings together SpongeBob and The Fairly OddParents. Fight robots under the sea and travel through magical realms with Timmy, Cosmo, and Wanda.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants---supersponge-&-battle-for-bikini-bottom-esir-vg', 'GAMEBOYADVANCE', '2 in 1 - SpongeBob Squarepants - Supersponge & Battle for Bikini Bottom (E)(Sir VG)', '2001', 'Platform', 'Climax Studios', '1', 'Platformer', 'Side-scrolling platformer and action-adventure levels.', 'Complete SpongeBob''s errands and defeat the robot army.', 'Double the SpongeBob with SuperSponge and Battle for Bikini Bottom.', 'SpongeBob Squarepants SuperSponge & Battle for Bikini Bottom offers the ultimate underwater experience. Explore Bikini Bottom, collect items, and fight iconic villains in these two classic GBA platformers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants---supersponge-&-les-razmoket-rencontrent-les-delajungle-eindependent', 'GAMEBOYADVANCE', '2 in 1 - SpongeBob SquarePants - SuperSponge & Les Razmoket Rencontrent les Delajungle (E)(Independent)', '2001', 'Platform', 'Climax Studios', '1', 'Platformer', 'Side-scrolling platformer and island-based adventure.', 'Complete errands as SpongeBob and survive the jungle with the Rugrats.', 'SpongeBob meets the Rugrats in this Nickelodeon cross-over pack.', 'SpongeBob SquarePants SuperSponge & Rugrats Go Wild (French version) features aquatic platforming and jungle exploration. Help SpongeBob with his tasks and then join the Rugrats on their wild island adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants---supersponge-&-rugrats---go-wild-eindependent', 'GAMEBOYADVANCE', '2 in 1 - SpongeBob Squarepants - Supersponge & Rugrats - Go Wild (E)(Independent)', '2001', 'Platform', 'Climax Studios', '1', 'Platformer', 'Side-scrolling platformer and island-based adventure.', 'Complete errands as SpongeBob and survive the jungle with the Rugrats.', 'SpongeBob meets the Rugrats in this Nickelodeon cross-over pack.', 'SpongeBob Squarepants SuperSponge & Rugrats Go Wild delivers two Nicktoon hits. Experience SpongeBob''s classic GBA debut and then join the Rugrats and the Wild Thornberrys in a tropical survival adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants-battle-for-bikini-bottom-&-jimmy-neutron-boy-genius-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Spongebob Squarepants Battle for Bikini Bottom & Jimmy Neutron Boy Genius (E)(Independent)', '2003', 'Platform', 'Heavy Iron Studios', '1', 'Platformer', 'Side-scrolling platforming and top-down adventure.', 'Save Bikini Bottom and help Jimmy Neutron save the world.', 'The ultimate Nicktoon duo featuring SpongeBob and Jimmy Neutron.', 'Battle for Bikini Bottom & Jimmy Neutron Boy Genius brings the best of Nickelodeon to GBA. Fight robots with SpongeBob and then use Jimmy''s inventions to stop an alien invasion in this action-packed pack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spongebob-squarepants-battle-for-bikini-bottom-&-nicktoons-freeze-frame-frenzy-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - SpongeBob Squarepants Battle for Bikini Bottom & Nicktoons Freeze Frame Frenzy (U)(Sir VG)', '2003', 'Platform', 'Heavy Iron Studios', '1', 'Platformer', 'Side-scrolling platforming and photography-based action.', 'Save Bikini Bottom and photograph characters across the Nickverse.', 'Fight as SpongeBob and take photos with the Nicktoons crew.', 'Battle for Bikini Bottom & Nicktoons Freeze Frame Frenzy offers variety. After saving the sea as SpongeBob, jump into a cross-over adventure where you must photograph characters from all your favorite Nick shows.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spy-hunter-&-super-sprint-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Spy Hunter & Super Sprint (E)(sUppLeX)', '2002', 'Action', 'Midway', '1', 'Arcade Action', 'Combat driving and top-down arcade racing.', 'Destroy enemy vehicles and win high-speed track races.', 'Classic arcade action with Spy Hunter''s gadgets and Super Sprint''s speed.', 'Spy Hunter & Super Sprint 2-in-1 brings retro thrills to GBA. Drive the weaponized Interceptor to take down terrorists and then test your reflexes in the tight, top-down circuits of Super Sprint.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spy-hunter-&-super-sprint-utrashman', 'GAMEBOYADVANCE', '2 in 1 - Spy Hunter & Super Sprint (U)(Trashman)', '2002', 'Action', 'Midway', '1', 'Arcade Action', 'Combat driving and top-down arcade racing.', 'Destroy enemy vehicles and win high-speed track races.', 'Classic arcade action with Spy Hunter''s gadgets and Super Sprint''s speed.', 'Spy Hunter & Super Sprint 2-in-1 brings retro thrills to GBA. Drive the weaponized Interceptor to take down terrorists and then test your reflexes in the tight, top-down circuits of Super Sprint.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spyro---fusion-&-crash-bandicoot---fusion-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Spyro - Fusion & Crash Bandicoot - Fusion (E)(Rising Sun)', '2004', 'Action', 'Vicarious Visions', '1', 'Action Adventure', 'Crossover platforming and mini-game challenges.', 'Stop the alliance between Ripto and Dr. Cortex.', 'Spyro and Crash join forces in an epic crossover event.', 'Spyro Fusion & Crash Bandicoot Fusion (European version) connects the two franchises. Play through themed mini-games and platforming segments to stop the villains from merging their worlds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spyro---season-of-ice-&-crash-bandicoot-2---n-tranced-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Spyro - Season of Ice & Crash Bandicoot 2 - N-Tranced (E)(Rising Sun)', '2002', 'Platform', 'Vicarious Visions', '1', 'Platformer', 'Isometric adventure and side-scrolling platformer.', 'Save the fairies and defeat N. Tranced''s minions.', 'An epic dragon adventure paired with a classic marsupial platformer.', 'Spyro: Season of Ice & Crash Bandicoot 2: N-Tranced offers a massive amount of gameplay. Explore the Dragon Realms in isometric 3D and then tackle the precision platforming levels of Crash''s second GBA outing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spyro---season-of-ice-&-spyro---season-of-flame-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Spyro - Season of Ice & Spyro - Season of Flame (U)(Independent)', '2004', 'Platform', 'Vicarious Visions', '1', 'Platformer', 'Isometric adventure and flame-based puzzle platforming.', 'Save the fairies and recover the stolen fireflies.', 'The complete early Spyro GBA trilogy journey in one pack.', 'Spyro: Season of Ice & Season of Flame brings the definitive Spyro experience to handheld. Explore vast worlds, breathe fire, and solve environmental puzzles to restore peace to the Dragon Realms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---spyro-2---season-of-flame-&-crash-nitro-kart-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Spyro 2 - Season of Flame & Crash Nitro Kart (E)(Rising Sun)', '2005', 'Racing', 'Vicarious Visions', '1', 'Arcade Racing', 'Isometric puzzle-platforming and high-speed kart racing.', 'Recover the fireflies and win the intergalactic racing cup.', 'Fire-breathing adventure meets high-octane kart racing.', 'Spyro 2: Season of Flame & Crash Nitro Kart is a high-value bundle. Enjoy the deep exploration and power-ups of Spyro’s sequel and then hit the tracks for some of the best kart racing on the GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---teenage-mutant-ninja-turtles-double-pack-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Teenage Mutant Ninja Turtles Double Pack (E)(sUppLeX)', '2003', 'Action', 'Konami', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up and action adventure.', 'Defeat the Shredder and protect the streets of New York.', 'Two TMNT brawlers in one shell-shocking double pack.', 'The TMNT Double Pack for GBA features the best of the ninja turtles. Experience fast-paced martial arts combat, use unique character weapons, and stop the Foot Clan in these two classic action titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---the-incredibles-&-finding-nemo---the-continuing-adventure-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - The Incredibles & Finding Nemo - The Continuing Adventure (U)(Sir VG)', '2004', 'Platform', 'Disney Interactive', '1', 'Platformer', 'Side-scrolling action and underwater puzzle-platforming.', 'Save the world as the Incredibles and find Nemo again.', 'Superhero combat meets aquatic exploration in this Pixar pack.', 'The Incredibles & Finding Nemo: The Continuing Adventure brings two Pixar sequels to GBA. Fight as Mr. Incredible and his family, then return to the ocean for more challenging levels with Nemo and Dory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---the-spongebob-squarepants-movie-&-freeze-frame-frenzy-esir-vg', 'GAMEBOYADVANCE', '2 in 1 - The SpongeBob SquarePants Movie & Freeze Frame Frenzy (E)(Sir VG)', '2004', 'Platform', 'Heavy Iron Studios', '1', 'Platformer', 'Platforming and photography-based missions.', 'Reach Shell City to save Neptune and snap photos of Nicktoons.', 'Relive the SpongeBob Movie and capture moments with Nick characters.', 'The SpongeBob SquarePants Movie & Freeze Frame Frenzy 2-in-1 pack offers diverse gameplay. Battle through movie-inspired levels to find King Neptune''s crown, then switch to the cross-over fun of photographing your favorite Nickelodeon stars in high-speed challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---titeuf-ze-gagmachine-&-titeuf-mega-compet-feternity', 'GAMEBOYADVANCE', '2 in 1 - Titeuf Ze Gagmachine & Titeuf Mega Compet (F)(Eternity)', '2004', 'Party', 'Eternity Studios', '1', 'Party', 'Mini-game collection and arcade challenges.', 'Win various playground competitions and complete humor-filled tasks.', 'Join Titeuf in a series of wacky and competitive mini-game challenges.', 'Titeuf Ze Gagmachine & Mega Compet brings the popular French comic character to GBA. This bundle is packed with hilarious mini-games and competitive modes that test your reflexes and sense of humor, perfect for fans of the series looking for portable fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---uno-&-skip-bo-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Uno & Skip-Bo (E)(sUppLeX)', '2004', 'Card', 'Mass Media', '4', 'Card Game', 'Digital card game simulation.', 'Be the first to play all your cards and reach the target score.', 'Two classic Mattel card games: UNO and Skip-Bo in one pack.', 'Uno & Skip-Bo for GBA is the ultimate portable card game collection. Experience faithful recreations of these family favorites with customizable rules and challenging AI opponents, making it perfect for quick gaming sessions anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---uno-&-skip-bo-usir-vg', 'GAMEBOYADVANCE', '2 in 1 - Uno & Skip-Bo (U)(Sir VG)', '2004', 'Card', 'Mass Media', '4', 'Card Game', 'Digital card game simulation.', 'Be the first to play all your cards and reach the target score.', 'Two classic Mattel card games: UNO and Skip-Bo in one pack.', 'Uno & Skip-Bo for GBA is the ultimate portable card game collection. Experience faithful recreations of these family favorites with customizable rules and challenging AI opponents, making it perfect for quick gaming sessions anywhere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---v-rally-3-&-stuntman-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - V-Rally 3 & Stuntman (E)(Rising Sun)', '2002', 'Racing', 'Eden Games', '1', 'Simulation Racing', 'Professional rally racing and stunt driving simulation.', 'Win the rally world championship and perform dangerous movie stunts.', 'High-speed rally racing meets high-stakes Hollywood stunt driving.', 'V-Rally 3 & Stuntman is a powerhouse racing combo. Experience the most advanced rally physics on GBA with V-Rally 3, and then master precision driving and spectacular crashes as a professional stuntman in iconic movie scenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---winnie-the-poohs-rumbly-tumbly-adventure-&-rayman-3-eindependent', 'GAMEBOYADVANCE', '2 in 1 - Winnie the Pooh''s Rumbly Tumbly Adventure & Rayman 3 (E)(Independent)', '2003', 'Platform', 'Ubisoft', '1', 'Platformer', 'Adventure platforming and 2D action exploration.', 'Find honey in the Hundred Acre Wood and stop André’s invasion.', 'A magical duo featuring Winnie the Pooh and Rayman’s third adventure.', 'Winnie the Pooh''s Rumbly Tumbly Adventure & Rayman 3 combines charm and action. Help Pooh find his favorite snacks through gentle puzzles and then switch to the fast-paced, imaginative world of Rayman to save the Teensies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---yu-gi-oh!---destiny-board-traveler-&-yu-gi-oh!---dungeon-dice-monsters-erising-sun', 'GAMEBOYADVANCE', '2 in 1 - Yu-Gi-Oh! - Destiny Board Traveler & Yu-Gi-Oh! - Dungeon Dice Monsters (E)(Rising Sun)', '2003', 'Strategy', 'KCEJ', '1', 'Strategy', 'Board-game strategy and dice-based tactical combat.', 'Win the board game tournament and master the art of dice dueling.', 'Two unique Yu-Gi-Oh! spin-offs focusing on strategy and luck.', 'Destiny Board Traveler & Dungeon Dice Monsters offers a different take on the Yu-Gi-Oh! universe. Move across game boards to defeat opponents and summon monsters via strategic dice rolls in these deep, tactical handheld titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---yu-gi-oh!-double-pack-esupplex', 'GAMEBOYADVANCE', '2 in 1 - Yu-Gi-Oh! Double Pack (E)(sUppLeX)', '2003', 'Strategy', 'KCEJ', '1', 'Strategy', 'Tactical card battling and RPG exploration.', 'Build the ultimate deck and win the Duel Monsters tournaments.', 'A double dose of Yu-Gi-Oh! card battling and tactical strategy.', 'The Yu-Gi-Oh! Double Pack delivers the classic Duel Monsters experience. Build your collection, refine your strategy, and face off against iconic duelists from the anime in these deep and addictive card-game simulations for GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('2-in-1---yu-gi-oh!-the-sacred-cards-&-yu-gi-oh!-reshef-of-destrcution-uindependent', 'GAMEBOYADVANCE', '2 in 1 - Yu-Gi-Oh! The Sacred Cards & Yu-Gi-Oh! Reshef Of Destrcution (U)(Independent)', '2004', 'RPG', 'KCEJ', '1', 'JRPG', 'Tactical card battling and RPG exploration.', 'Master the Egyptian God Cards and stop the resurrection of Reshef.', 'Two epic RPG-style Yu-Gi-Oh! adventures with deep card mechanics.', 'Yu-Gi-Oh! The Sacred Cards & Reshef of Destruction are story-driven card games. Explore the city of Domino, build powerful decks, and engage in high-stakes duels to save the world in these immersive RPG-style titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---asteroids-yars-revenge-and-pong-esupplex', 'GAMEBOYADVANCE', '3 in 1 - Asteroids, Yar''s Revenge and Pong (E)(sUppLeX)', '2001', 'Arcade', 'Atari', '2', 'Classic Arcade', 'Retro arcade action and high-score chasing.', 'Clear asteroids, defend the world, and win at classic table tennis.', 'Three legendary Atari arcade classics: Asteroids, Pong, and Yar''s Revenge.', '3 in 1 - Asteroids, Yar''s Revenge and Pong brings the birth of gaming to your GBA. Experience faithful ports of these arcade milestones, featuring simple but addictive gameplay that challenges your reflexes and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---candy-land-chutes-and-ladders-memory-utrashman', 'GAMEBOYADVANCE', '3 in 1 - Candy Land, Chutes and Ladders, Memory (U)(Trashman)', '2004', 'Party', 'Griptonite Games', '4', 'Board Game', 'Digital board game simulation.', 'Be the first to reach the end of the board in various childhood classics.', 'Three beloved board games: Candy Land, Chutes and Ladders, and Memory.', 'This 3-in-1 collection features classic Hasbro board games. Perfect for younger players, it offers digital versions of Candy Land, Chutes and Ladders, and Memory, providing wholesome, easy-to-learn fun on a single cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---darts-&-shuffle-and-skiball-erising-sun', 'GAMEBOYADVANCE', '3 in 1 - Darts & Shuffle and Skiball (E)(Rising Sun)', '2003', 'Sports', 'Cosmic Concepts', '4', 'Casual Sports', 'Casual sports simulation and arcade mini-games.', 'Score the highest points in Darts, Shuffleboard, and Skiball.', 'A fun collection of pub and boardwalk classics for your handheld.', '3 in 1 - Darts & Shuffle and Skiball offers casual gaming at its best. Master the precision of dart throwing and the physics of skiball in this variety pack designed for short, competitive gaming sessions on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---ker-plunk!-&-toss-across-&-tip-it-usir-vg', 'GAMEBOYADVANCE', '3 in 1 - Ker Plunk! & Toss Across & Tip It (U)(Sir VG)', '2003', 'Party', 'Black Lantern Studios', '4', 'Party', 'Physics-based casual games and arcade puzzles.', 'Keep the marbles in, balance the tips, and win the toss.', 'Three classic physical toy games translated into digital fun.', '3 in 1 - Ker Plunk! & Toss Across & Tip It brings iconic physical games to the GBA. These digital adaptations challenge your timing and precision, offering a nostalgic and fun experience for fans of the original tabletop toys.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---life-yahtzee-payday-utrashman', 'GAMEBOYADVANCE', '3 in 1 - Life, Yahtzee, Payday (U)(Trashman)', '2003', 'Board', 'Mass Media', '4', 'Board Game', 'Digital board game and lifestyle simulation.', 'Earn the most money, get lucky with dice, and win at Life.', 'Three classic Hasbro board games: Life, Yahtzee, and Payday.', 'Experience the thrill of Life, the strategy of Yahtzee, and the financial management of Payday in this comprehensive 3-in-1 pack. It’s the perfect way to bring family board game night to your Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---majescos-rec-room-challenge-usir-vg', 'GAMEBOYADVANCE', '3 in 1 - Majesco''s Rec Room Challenge (U)(Sir VG)', '2003', 'Party', 'Majesco', '4', 'Party', 'Casual arcade and parlor game simulation.', 'Master billiards, air hockey, and other rec room classics.', 'A great collection of classic parlor games for casual play.', 'Majesco''s Rec Room Challenge brings the basement fun to your pocket. Featuring Billiards, Air Hockey, and more, this collection focuses on realistic physics and simple controls for an authentic casual gaming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---majescos-sports-pack-erising-sun', 'GAMEBOYADVANCE', '3 in 1 - Majesco''s Sports Pack (E)(Rising Sun)', '2002', 'Sports', 'Torus Games', '4', 'Sports', 'Arcade-style sports simulation.', 'Win championships in football, basketball, and baseball.', 'A compact sports collection featuring three major athletic games.', 'Majesco''s Sports Pack provides a variety of athletic challenges. From the gridiron to the court, these arcade-style sports titles offer fast-paced action and accessible controls for sports fans looking for a quick match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---majescos-sports-pack-usir-vg', 'GAMEBOYADVANCE', '3 in 1 - Majesco''s Sports Pack (U)(Sir VG)', '2002', 'Sports', 'Torus Games', '4', 'Sports', 'Arcade-style sports simulation.', 'Win championships in football, basketball, and baseball.', 'A compact sports collection featuring three major athletic games.', 'Majesco''s Sports Pack (US Version) delivers three diverse sports experiences on one cartridge. Compete in stylized versions of popular American sports, featuring colorful graphics and intuitive handheld gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---mousetrap-&-simon-&-operation-uindependent', 'GAMEBOYADVANCE', '3 in 1 - Mousetrap & Simon & Operation (U)(Independent)', '2003', 'Party', 'Black Lantern Studios', '4', 'Party', 'Action-puzzles and reflex-based casual games.', 'Capture the mouse, follow the lights, and perform surgery.', 'Three iconic Milton Bradley games: Mouse Trap, Simon, and Operation.', '3 in 1 - Mousetrap & Simon & Operation offers digital versions of classic mechanical games. Test your memory with Simon, your steady hand with Operation, and your puzzle-solving skills with the intricate Mouse Trap.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---rugrats-spongebob-tak-eindependent', 'GAMEBOYADVANCE', '3 in 1 - Rugrats, SpongeBob, Tak (E)(Independent)', '2003', 'Platform', 'THQ', '1', 'Platformer', 'Side-scrolling platforming and action-adventure.', 'Complete diverse quests with your favorite Nickelodeon heroes.', 'A powerhouse Nickelodeon trio featuring Rugrats, SpongeBob, and Tak.', 'This 3-in-1 pack features Nickelodeon''s biggest stars. Explore the ocean with SpongeBob, go on an adventure with the Rugrats, and use juju magic with Tak in this action-packed handheld compilation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('3-in-1---super-breakout-lunar-lander-and-millipede-esupplex', 'GAMEBOYADVANCE', '3 in 1 - Super Breakout, Lunar Lander and Millipede (E)(sUppLeX)', '2001', 'Arcade', 'Atari', '2', 'Classic Arcade', 'Retro arcade action and high-score chasing.', 'Break all the bricks, land the module, and stop the centipedes.', 'Three Atari arcade hits: Super Breakout, Lunar Lander, and Millipede.', '3 in 1 - Super Breakout, Lunar Lander and Millipede is a must-have for retro fans. Master the physics of gravity in Lunar Lander and the twitch-shooting intensity of Millipede in this classic arcade bundle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4-games-on-one-game-pak---nickelodeon-usir-vg', 'GAMEBOYADVANCE', '4 Games On One Game Pak - Nickelodeon (U)(Sir VG)', '2003', 'Compilation', 'Nickelodeon', '1', 'Party', 'Multi-genre Nickelodeon adventures.', 'Complete various missions with SpongeBob, Rugrats, and more.', 'Four incredible Nickelodeon games on one single Game Boy cartridge.', '4 Games On One Game Pak - Nickelodeon offers massive value. Featuring a mix of platforming, puzzles, and adventure from the most popular Nick shows, this pack provides hours of diverse gameplay for fans of all ages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4-in-1---gt-advance-&-gt-advance-2-&-gt-advance-3-&-moto-gp-usir-vg', 'GAMEBOYADVANCE', '4 in 1 - GT Advance & GT Advance 2 & GT Advance 3 & Moto GP (U)(Sir VG)', '2003', 'Racing', 'MTO', '1', 'Simulation Racing', 'Simulation and arcade racing across different vehicles.', 'Win the GT championships and dominate the MotoGP circuit.', 'The ultimate racing collection: Three GT Advance games and MotoGP.', 'This 4-in-1 racing pack is the definitive GBA driving collection. Experience deep car customization and realistic physics in the GT Advance trilogy, and then master the leaning mechanics of pro bike racing in MotoGP.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('4v4-arashi-get-the-goal-jquartex', 'GAMEBOYADVANCE', '4V4 Arashi Get The Goal (J)(Quartex)', '2002', 'Sports', 'Square Enix', '4', 'Sports', 'Top-down soccer/football action.', 'Score goals and win the national soccer tournament.', 'Intense arcade-style soccer action with a classic Japanese flair.', '4V4 Arashi Get The Goal is a fast-paced soccer title for GBA. Focus on small-team tactics, quick passes, and powerful shots in this energetic sports game that captures the spirit of arcade football.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-more-modern-amazing-mirror', 'GAMEBOYADVANCE', 'A More Modern Amazing Mirror', '2004', 'Platform', 'HAL Laboratory', '1', 'Platformer', 'Action-adventure with exploration and copy abilities.', 'Explore the mirror world and defeat the dark presence within.', 'A modern take on the classic Kirby adventure in the mirror world.', 'Experience a refined version of Kirby''s classic adventure. Navigate a massive interconnected world, use unique copy abilities to solve puzzles, and team up with different Kirby colors to save the Mirror World from darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-sound-of-thunder-erising-sun', 'GAMEBOYADVANCE', 'A Sound of Thunder (E)(Rising Sun)', '2005', 'Action', 'Mobius Entertainment', '1', 'Action Adventure', 'Action-adventure with stealth and shooting elements.', 'Survive the butterfly effect and fix the timeline in a prehistoric past.', 'A sci-fi thriller based on the Ray Bradbury story and movie.', 'A Sound of Thunder for GBA combines top-down action with a compelling sci-fi narrative. Fight mutated creatures, solve environmental puzzles, and correct a fractured timeline in this atmospheric and challenging title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('a-sound-of-thunder-utrashman', 'GAMEBOYADVANCE', 'A Sound of Thunder (U)(TrashMan)', '2005', 'Action', 'Mobius Entertainment', '1', 'Action Adventure', 'Action-adventure with stealth and shooting elements.', 'Survive the butterfly effect and fix the timeline in a prehistoric past.', 'A sci-fi thriller based on the Ray Bradbury story and movie.', 'A Sound of Thunder for GBA combines top-down action with a compelling sci-fi narrative. Fight mutated creatures, solve environmental puzzles, and correct a fractured timeline in this atmospheric and challenging title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ab-durch-die-hecke-glightforce', 'GAMEBOYADVANCE', 'Ab Durch die Hecke (G)(LightForce)', '2006', 'Platform', 'Vicarious Visions', '1', 'Platformer', 'Stealth-based platforming and adventure tasks.', 'Help RJ and his friends raid the suburbs for snacks and supplies.', 'The German version of Over the Hedge, featuring stealthy animal fun.', 'Ab Durch die Hecke brings the humor of the movie to the GBA. Use the unique skills of RJ, Verne, and Hammy to sneak past humans and traps in a series of fun, stealth-oriented platforming levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-combat-advance-uvenom', 'GAMEBOYADVANCE', 'Ace Combat Advance (U)(Venom)', '2001', 'Simulation', 'Namco', '1', 'Flight Simulation', 'Arcade flight combat and mission-based aerial action.', 'Complete various flight missions and defeat enemy squadrons.', 'High-flying combat action from the legendary Ace Combat series.', 'Ace Combat Advance brings the thrill of dogfighting to the handheld. Pilot advanced fighter jets, manage your weapons, and engage in tactical aerial missions in this impressive GBA entry for the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ace-lightning-emode7', 'GAMEBOYADVANCE', 'Ace Lightning (E)(Mode7)', '2003', 'Action', 'Razorback Developments', '1', 'Action Adventure', 'Action-platformer with combat and puzzle elements.', 'Defeat Lord Fear and his minions across the digital realm.', 'Play as the superhero Ace Lightning in this action-packed adventure.', 'Based on the hit TV show, Ace Lightning for GBA lets you battle through diverse levels to collect the pieces of the Amulet of Elvar. Use magical lightning attacks and master platforming challenges to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('acrobat-kid-jcezar', 'GAMEBOYADVANCE', 'Acrobat Kid (J)(Cezar)', '1999', 'Platform', 'Future Vision Music', '1', 'Platformer', 'Precision platforming and acrobatic action.', 'Complete circus-themed levels with agility and timing.', 'A colorful and challenging Japanese platformer with acrobatic moves.', 'Acrobat Kid is a hidden gem for the GBA. Featuring fluid animations and creative level design, you must use your acrobatic skills to navigate treacherous obstacles in this high-energy, classic 2D platforming adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('action-man---robot-atak-erising-sun', 'GAMEBOYADVANCE', 'Action Man - Robot Atak (E)(Rising Sun)', '2004', 'Action', 'Magic Pockets', '1', 'Action Adventure', 'Side-scrolling action platforming with combat.', 'Stop the robot invasion and defeat the villainous No-Face.', 'Join Action Man in a high-stakes battle against a robotic army.', 'Action Man - Robot Atak brings the iconic hero to GBA. Navigate through dangerous environments, use high-tech weaponry, and master platforming challenges to thwart a robotic global threat in this action-packed handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('activision-anthology-ueurasia', 'GAMEBOYADVANCE', 'Activision Anthology (U)(Eurasia)', '2002', 'Compilation', 'Activision', '1', 'Classic Arcade', 'Classic arcade compilation and retro simulation.', 'Achieve high scores and unlock classic Atari 2600 games.', 'Over 40 legendary Atari 2600 classics in one single collection.', 'Activision Anthology is a nostalgic treasure for GBA. Featuring hits like Pitfall! and River Raid, this compilation offers authentic retro gameplay, unlockable rewards, and a virtual 80s bedroom interface for the ultimate trip down memory lane.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-gt2-jeurasia', 'GAMEBOYADVANCE', 'Advance GT2 (J)(Eurasia)', '2001', 'Racing', 'MTO', '1', 'Arcade Racing', 'Simulation racing with car customization.', 'Win the grand prix and upgrade your racing fleet.', 'Deep car tuning and high-speed racing action for enthusiasts.', 'Advance GT2 delivers a realistic driving experience on GBA. Master the art of the drift, customize your engine and tires, and compete in diverse weather conditions to become the champion of the professional racing circuit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-gta-jcapital', 'GAMEBOYADVANCE', 'Advance GTA (J)(Capital)', '2002', 'Racing', 'MTO', '1', 'Arcade Racing', 'Arcade-style racing and top-down driving.', 'Finish first in every race to unlock new tracks and cars.', 'Fast-paced racing action with a classic Japanese arcade feel.', 'Advance GTA offers high-velocity fun on your handheld. Featuring intuitive controls and a variety of vehicles, this title focuses on pure speed and competitive AI, making it a great pick for racing fans on the go.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-guardian-heroes-erisingcaravan', 'GAMEBOYADVANCE', 'Advance Guardian Heroes (E)(RisingCaravan)', '2004', 'Action', 'Treasure', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up with RPG elements.', 'Defeat waves of enemies and save the kingdom from chaos.', 'A frantic and flashy brawler with deep combat mechanics.', 'Advance Guardian Heroes is the spiritual successor to the Saturn classic. Choose your hero, level up your stats, and engage in chaotic, multi-lane combat with spectacular magical attacks and intense boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-guardian-heroes-jcaravan', 'GAMEBOYADVANCE', 'Advance Guardian Heroes (J)(Caravan)', '2004', 'Action', 'Treasure', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up with RPG elements.', 'Defeat waves of enemies and save the kingdom from chaos.', 'A frantic and flashy brawler with deep combat mechanics.', 'Advance Guardian Heroes (Japanese Version) brings the same high-octane fighting action to the GBA. Experience the deep story and branching paths that made this Treasure-developed brawler a cult favorite among action fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-guardian-heroes-uvenom', 'GAMEBOYADVANCE', 'Advance Guardian Heroes (U)(Venom)', '2004', 'Action', 'Treasure', '1', 'Beat ''em Up', 'Side-scrolling beat ''em up with RPG elements.', 'Defeat waves of enemies and save the kingdom from chaos.', 'A frantic and flashy brawler with deep combat mechanics.', 'Advance Guardian Heroes (US Version) delivers pixel-perfect brawling. With a variety of playable characters and a complex magic system, it offers one of the most intense and rewarding action experiences on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-rally-jeurasia', 'GAMEBOYADVANCE', 'Advance Rally (J)(Eurasia)', '2001', 'Racing', 'Kuju Entertainment', '1', 'Arcade Racing', 'Off-road rally racing simulation.', 'Master the dirt tracks and win the international rally trophy.', 'Intense rally racing with realistic handling and terrain.', 'Advance Rally challenges your driving skills on the toughest surfaces. Navigate sharp turns and diverse weather across multiple global locations in this impressively technical handheld racing simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-earrogance', 'GAMEBOYADVANCE', 'Advance Wars (E)(Arrogance)', '2001', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy and war simulation.', 'Use your Commanding Officer powers to defeat enemy armies.', 'The definitive handheld strategy game featuring grid-based combat.', 'Advance Wars sets the gold standard for GBA strategy. Command land, sea, and air units, capture cities, and use unique CO powers to outsmart the enemy in a deep, rewarding tactical campaign.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-umode7', 'GAMEBOYADVANCE', 'Advance Wars (U)(Mode7)', '2001', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy and war simulation.', 'Use your Commanding Officer powers to defeat enemy armies.', 'The definitive handheld strategy game featuring grid-based combat.', 'Advance Wars (US Version) offers the same addictive tactical depth. Build your army, manage resources, and engage in high-stakes warfare across a variety of challenging maps and mission scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-ux-syte', 'GAMEBOYADVANCE', 'Advance Wars (U)(X-Syte)', '2001', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy and war simulation.', 'Use your Commanding Officer powers to defeat enemy armies.', 'The definitive handheld strategy game featuring grid-based combat.', 'Advance Wars (US Release) brings intense military strategy to your pocket. Master the strengths and weaknesses of different units and lead your battalion to victory in this highly acclaimed turn-based title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-2---black-hole-rising-esurplus', 'GAMEBOYADVANCE', 'Advance Wars 2 - Black Hole Rising (E)(Surplus)', '2003', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy and war simulation.', 'Reclaim the continent from the invading Black Hole Army.', 'The epic sequel featuring new COs, units, and a massive campaign.', 'Advance Wars 2: Black Hole Rising expands on the original''s success. With more powerful CO abilities and the introduction of new Super CO powers, it offers a deeper and more challenging tactical experience for veteran commanders.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-2---black-hole-rising-umode7', 'GAMEBOYADVANCE', 'Advance Wars 2 - Black Hole Rising (U)(Mode7)', '2003', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy and war simulation.', 'Reclaim the continent from the invading Black Hole Army.', 'The epic sequel featuring new COs, units, and a massive campaign.', 'Advance Wars 2: Black Hole Rising (US Version) takes the fight to a global scale. Fight across different nations, utilize new unit types like Neotanks, and stop the Black Hole invasion in this strategy masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('advance-wars-returns', 'GAMEBOYADVANCE', 'Advance Wars Returns', '2008', 'Strategy', 'Intelligent Systems', '4', 'Turn-Based Strategy', 'Turn-based tactical strategy (Fan/ROM hack style).', 'Command your units to victory in custom tactical scenarios.', 'A refined take on the classic Advance Wars formula with new twists.', 'Advance Wars Returns offers fans a fresh perspective on the tactical gameplay they love. Featuring challenging new maps and balanced unit mechanics, it’s a perfect addition for those who have mastered the original series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('adventure-of-tokyo-disney-sea-jeurasia', 'GAMEBOYADVANCE', 'Adventure of Tokyo Disney Sea (J)(Eurasia)', '2002', 'Adventure', 'Disney Interactive', '1', 'Adventure', 'Theme park adventure and mini-game collection.', 'Explore the Disney Sea park and complete magical missions.', 'A charming journey through the famous Tokyo Disney Sea park.', 'Adventure of Tokyo Disney Sea allows players to experience the magic of the Japanese theme park. Engage in various mini-games and explore themed lands with beloved Disney characters in this delightful adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat---rascal-rival-revenge-eindependent', 'GAMEBOYADVANCE', 'Aero The Acro-Bat - Rascal Rival Revenge (E)(Independent)', '2002', 'Platform', 'Iguana Entertainment', '1', 'Platformer', 'High-flying circus platforming and action.', 'Save the circus from the villainous Edgar Ektor.', 'Classic acrobatic platforming with a high-flying bat hero.', 'Aero The Acro-Bat - Rascal Rival Revenge brings the 16-bit icon to GBA. Use Aero''s drill attack and acrobatic skills to navigate through deadly circus environments and stop the evil clown''s plot in this vibrant platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aero-the-acro-bat---rascal-rival-revenge-umode7', 'GAMEBOYADVANCE', 'Aero The Acro-Bat - Rascal Rival Revenge (U)(Mode7)', '2002', 'Platform', 'Iguana Entertainment', '1', 'Platformer', 'High-flying circus platforming and action.', 'Save the circus from the villainous Edgar Ektor.', 'Classic acrobatic platforming with a high-flying bat hero.', 'Aero The Acro-Bat (US Version) delivers the same fast-paced, colorful action. With refined controls and challenging level design, it’s a faithful port of the cult classic that tests your timing and reflexes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('agassi-tennis-generation-urising-sun', 'GAMEBOYADVANCE', 'Agassi Tennis Generation (U)(Rising Sun)', '2003', 'Sports', 'Aqua Pacific', '2', 'Tennis', 'Realistic tennis simulation and sports management.', 'Climb the world rankings and win the Grand Slam.', 'Professional tennis action featuring the legendary Andre Agassi.', 'Agassi Tennis Generation offers a comprehensive tennis experience. Master different court surfaces, refine your serve and volley game, and compete against the world''s best in this deep handheld sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('agassi-tennis-generation-2002-emode7', 'GAMEBOYADVANCE', 'Agassi Tennis Generation 2002 (E)(Mode7)', '2002', 'Sports', 'Aqua Pacific', '2', 'Tennis', 'Realistic tennis simulation and sports management.', 'Climb the world rankings and win the Grand Slam.', 'Professional tennis action featuring the legendary Andre Agassi.', 'Agassi Tennis Generation 2002 features updated rosters and refined graphics. Experience the intensity of professional tennis with realistic ball physics and various game modes, including career and quick match.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('agent-hugo---roborumble-erising-sun', 'GAMEBOYADVANCE', 'Agent Hugo - Roborumble (E)(Rising Sun)', '2003', 'Action', 'Ite Media', '1', 'Action Adventure', 'High-speed kart racing and combat.', 'Defeat the robot invaders in a series of racing challenges.', 'Join Agent Hugo in a race to save the world from machines.', 'Agent Hugo - Roborumble combines racing with action-adventure. Drive futuristic vehicles, use powerful power-ups, and navigate hazardous tracks to stop the Roborumble threat in this energetic GBA title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aggressive-inline-epatience', 'GAMEBOYADVANCE', 'Aggressive Inline (E)(Patience)', '2002', 'Sports', 'Z-Axis', '1', 'Extreme Sports', 'Extreme sports skating and trick-based action.', 'Complete trick objectives and earn pro skater status.', 'High-octane inline skating with a focus on style and speed.', 'Aggressive Inline brings the thrill of extreme skating to GBA. Perform massive grinds, airs, and wall-rides across expansive urban environments to unlock new gear and levels in this deep sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aggressive-inline-ueurasia', 'GAMEBOYADVANCE', 'Aggressive Inline (U)(Eurasia)', '2002', 'Sports', 'Z-Axis', '1', 'Extreme Sports', 'Extreme sports skating and trick-based action.', 'Complete trick objectives and earn pro skater status.', 'High-octane inline skating with a focus on style and speed.', 'Aggressive Inline (US Version) features a robust trick system and licensed soundtrack vibes. Master the "juice" meter to keep your combos going and prove you are the best skater in the park.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('airforce-delta-ii-jindependent', 'GAMEBOYADVANCE', 'AirForce Delta II (J)(Independent)', '2003', 'Simulation', 'Konami', '1', 'Flight Combat', 'Arcade flight combat and aerial missions.', 'Pilot advanced fighter jets and complete tactical objectives.', 'Intense dogfighting and flight simulation in the AirForce Delta series.', 'AirForce Delta II brings high-flying action to the GBA. Choose from a variety of real-world aircraft and engage in cinematic aerial combat across multiple mission types, from escorting bombers to destroying enemy bases.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('airforce-delta-storm-umode7', 'GAMEBOYADVANCE', 'AirForce Delta Storm (U)(Mode7)', '2002', 'Simulation', 'Konami', '1', 'Flight Combat', 'Arcade flight combat and aerial missions.', 'Pilot advanced fighter jets and complete tactical objectives.', 'Intense dogfighting and flight simulation in the AirForce Delta series.', 'AirForce Delta Storm (US Version) offers a thrilling arcade-style flight experience. With impressive sprite-based scaling and fast-paced combat, it challenges you to master the skies and defeat enemy squadrons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akachan-doubutsuen-jcaravan', 'GAMEBOYADVANCE', 'Akachan Doubutsuen (J)(Caravan)', '2001', 'Educational', 'Graphic Research', '1', 'Educational', 'Animal care and virtual pet simulation.', 'Take care of adorable baby animals in a zoo setting.', 'A cute and relaxing simulation game for animal lovers.', 'Akachan Doubutsuen is a charming Japanese title where you manage a nursery for baby animals. Feed, groom, and play with various creatures to keep them happy and healthy in this cozy handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akagi-jcaravan', 'GAMEBOYADVANCE', 'Akagi (J)(Caravan)', '2002', 'Board', 'Game Studio', '1', 'Board Game', 'Mahjong simulation and strategy.', 'Defeat opponents in high-stakes Mahjong matches.', 'A deep Mahjong experience based on the popular manga series.', 'Akagi for GBA brings the tension of the gambling world to your pocket. Master the complex rules of Mahjong and use your strategic wit to outplay rivals in this faithful adaptation of the dark, legendary series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---circle-of-the-moon-ctitan', 'GAMEBOYADVANCE', 'Akumajou Dracula - Circle of the Moon (C)(Titan)', '2001', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action-RPG (Metroidvania).', 'Explore the castle and seal the dark count once again.', 'The legendary first Castlevania entry for the GBA.', 'Akumajou Dracula - Circle of the Moon (Japanese Version) features the deep "Dual Set-up System" (DSS). Combine cards to create magical effects, explore a massive gothic castle, and battle iconic monsters in this dark masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('akumajou-dracula---circle-of-the-moon-jcapital', 'GAMEBOYADVANCE', 'Akumajou Dracula - Circle of the Moon (J)(Capital)', '2001', 'Action', 'Konami', '1', 'Action Platformer', 'Side-scrolling action-RPG (Metroidvania).', 'Explore the castle and seal the dark count once again.', 'The legendary first Castlevania entry for the GBA.', 'Akumajou Dracula - Circle of the Moon delivers a gothic atmosphere and challenging gameplay. Explore Dracula’s castle, master the whip, and collect magic cards to survive one of the most acclaimed titles on the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aleck-bordon-adventure---tower-&-shaft-advance-jtrashman', 'GAMEBOYADVANCE', 'Aleck Bordon Adventure - Tower & Shaft Advance (J)(Trashman)', '2003', 'Platform', 'Taito', '1', 'Platformer', 'Vertical climbing and action-puzzle gameplay.', 'Reach the top of various towers while avoiding obstacles.', 'A fast-paced arcade challenge focused on climbing and dodging.', 'Aleck Bordon Adventure: Tower & Shaft Advance is a unique Japanese title. Test your reflexes as you climb ever-higher, avoiding traps and enemies in a race against time and gravity in this addictive arcade-style game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-rider---stormbreaker-esir-vg', 'GAMEBOYADVANCE', 'Alex Rider - Stormbreaker (E)(Sir VG)', '2006', 'Action', 'Griptonite Games', '1', 'Action Adventure', 'Stealth-based action and gadget-driven exploration.', 'Complete spy missions based on the Alex Rider movie.', 'Live the life of a teenage spy in this intense action game.', 'Alex Rider - Stormbreaker brings the movie''s thrills to GBA. Use clever gadgets, engage in hand-to-hand combat, and complete stealth objectives to stop a global conspiracy in this high-tech handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alex-rider---stormbreaker-urising-sun', 'GAMEBOYADVANCE', 'Alex Rider - Stormbreaker (U)(Rising Sun)', '2006', 'Action', 'Griptonite Games', '1', 'Action Adventure', 'Stealth-based action and gadget-driven exploration.', 'Complete spy missions based on the Alex Rider movie.', 'Live the life of a teenage spy in this intense action game.', 'Alex Rider - Stormbreaker (US Version) features various gameplay styles, including combat and driving segments. Master the skills of a secret agent and survive the dangerous world of international espionage.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-hominid-etrashman', 'GAMEBOYADVANCE', 'Alien Hominid (E)(Trashman)', '2004', 'Action', 'The Behemoth', '1', 'Action Platformer', 'Fast-paced 2D side-scrolling run-and-gun action.', 'Fight off secret agents and reclaim your UFO to return home.', 'Intense arcade-style shooting with unique hand-drawn art.', 'Alien Hominid for GBA brings the legendary indie hit to your handheld. Experience chaotic run-and-gun gameplay, collect powerful power-ups, and battle massive bosses in this high-energy port known for its challenging difficulty and distinct visual style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alien-hominid-europe-enfrdeesit', 'GAMEBOYADVANCE', 'Alien Hominid (Europe) (En,Fr,De,Es,It)', '2004', 'Action', 'The Behemoth', '1', 'Action Platformer', 'Fast-paced 2D side-scrolling run-and-gun action.', 'Fight off secret agents and reclaim your UFO to return home.', 'Intense arcade-style shooting with unique hand-drawn art.', 'This European version of Alien Hominid features the same frantic shooting action. Navigate through levels filled with enemies, use your knife for close combat, and enjoy the quirky humor and stylized graphics that made this game a cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('alienators---evolution-continues-umode7', 'GAMEBOYADVANCE', 'Alienators - Evolution Continues (U)(Mode7)', '2001', 'Action', 'Software Creations', '1', 'Action Adventure', 'Side-scrolling platformer with shooting and combat.', 'Eradicate the evolving alien threat known as the Genus.', 'Join the Alienators team in a battle against biological mutations.', 'Based on the animated series, Alienators - Evolution Continues delivers solid platforming action. Use various high-tech weapons to dissolve alien organisms and navigate hazardous environments to save Earth from a biological takeover.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-grown-up---express-yourself-eindependent', 'GAMEBOYADVANCE', 'All Grown Up - Express Yourself (E)(Independent)', '2003', 'Party', 'Griptonite Games', '1', 'Casual', 'Adventure and social simulation with mini-games.', 'Navigate teenage life and complete personal creative tasks.', 'Express yourself with the All Grown Up gang in this social adventure.', 'All Grown Up - Express Yourself brings the Rugrats'' teenage counterparts to GBA. Interact with friends, solve puzzles, and engage in diverse mini-games that focus on fashion, creativity, and the social challenges of growing up.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-2003-uvenom', 'GAMEBOYADVANCE', 'All-Star Baseball 2003 (U)(Venom)', '2002', 'Sports', 'Acclaim Studios Austin', '1', 'Baseball', 'Realistic baseball simulation and sports management.', 'Win the World Series and master the diamond.', 'Professional baseball action featuring Derek Jeter and top MLB stars.', 'All-Star Baseball 2003 offers an authentic MLB experience. With realistic player stats, various stadiums, and multiple game modes including Season and Home Run Derby, it’s the definitive baseball title for handheld sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('all-star-baseball-2004-uvenom', 'GAMEBOYADVANCE', 'All-Star Baseball 2004 (U)(Venom)', '2003', 'Sports', 'Acclaim Studios Austin', '1', 'Baseball', 'Realistic baseball simulation and sports management.', 'Win the World Series and master the diamond.', 'Professional baseball action featuring Derek Jeter and top MLB stars.', 'All-Star Baseball 2004 improves upon its predecessor with refined gameplay and updated rosters. Master the art of pitching, batting, and fielding in this comprehensive baseball simulation designed for the GBA hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast---guardian-of-the-realms-etrashman', 'GAMEBOYADVANCE', 'Altered Beast - Guardian of the Realms (E)(TrashMan)', '2002', 'Action', '3DO Company', '1', 'Action Platformer', 'Side-scrolling beat ''em up with transformation mechanics.', 'Defeat the forces of Hades and save the celestial realms.', 'Rise from your grave and transform into powerful beasts to fight evil.', 'Altered Beast - Guardian of the Realms is a spiritual successor to the SEGA classic. Battle through diverse levels, collect orbs to transform into various mythical creatures, and use powerful elemental attacks to crush the undead.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-beast---guardian-of-the-realms-uvenom', 'GAMEBOYADVANCE', 'Altered Beast - Guardian of the Realms (U)(Venom)', '2002', 'Action', '3DO Company', '1', 'Action Platformer', 'Side-scrolling beat ''em up with transformation mechanics.', 'Defeat the forces of Hades and save the celestial realms.', 'Rise from your grave and transform into powerful beasts to fight evil.', 'The US version of Altered Beast offers intense brawling action. Experience the classic power-up system as you transform into a Werewolf, Dragon, or Minotaur to defeat massive bosses and save the world from darkness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('altered-emerald-41e', 'GAMEBOYADVANCE', 'Altered Emerald 4.1e', '2005', 'Hack', 'Independent', '1', 'ROM Hack', 'Creature collection and turn-based RPG battle system.', 'Become the champion and discover the secrets of altered forms.', 'A massive overhaul of the classic Emerald experience with new twists.', 'Altered Emerald 4.1e is a fan-favorite enhancement of the legendary RPG. Featuring expanded rosters, updated movesets, and challenging new encounters, it offers a fresh and modern way to experience the Hoenn region on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-bass-challenge-udumper', 'GAMEBOYADVANCE', 'American Bass Challenge (U)(Dumper)', '2003', 'Sports', 'Starfish', '1', 'Fishing', 'Fishing simulation with various lakes and gear.', 'Catch the biggest bass and win professional tournaments.', 'Realistic fishing action with a focus on strategy and lure selection.', 'American Bass Challenge brings the tranquility and tension of competitive fishing to GBA. Choose your equipment, find the best spots in various lakes, and manage your time to catch the heaviest haul in this deep simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-dragon---jake-long-urising-sun', 'GAMEBOYADVANCE', 'American Dragon - Jake Long (U)(Rising Sun)', '2005', 'Action', 'Artificial Mind & Movement', '1', 'Action Adventure', 'Side-scrolling action platformer with combat.', 'Protect the magical community of New York as the American Dragon.', 'Unleash your dragon powers to fight evil in the city.', 'Based on the Disney show, American Dragon - Jake Long features intense combat and platforming. Switch between Jake''s human form for stealth and his dragon form for raw power to defeat iconic villains and protect his friends.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('american-idol-umode7', 'GAMEBOYADVANCE', 'American Idol (U)(Mode7)', '2003', 'Music', 'Supersonic Software', '1', 'Rhythm', 'Rhythm-based singing and performance simulation.', 'Rise through the competition to become the next American Idol.', 'Test your rhythm and timing to impress the judges in this musical game.', 'American Idol for GBA lets you experience the hit TV show. Master the beat-matching gameplay to perform popular songs, earn high scores from the judges, and climb the ranks from auditions to the grand finale.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('amogus:-impostor-version', 'GAMEBOYADVANCE', 'Amogus: Impostor Version', '2023', 'Action', 'Independent', '1', 'Action', 'Social deduction and survival mini-games.', 'Identify the impostor or sabotage the crew to win.', 'A fan-made GBA demake of the global social deduction phenomenon.', 'Amogus: Impostor Version brings the "Sus" gameplay to retro hardware. Complete tasks as a crewmate or use vents and sabotage as an impostor in this creative 8-bit style reimagining of the modern multiplayer classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('an-american-tail---fievels-gold-rush-elightforce', 'GAMEBOYADVANCE', 'An American Tail - Fievel''s Gold Rush (E)(Lightforce)', '2002', 'Platform', '7th Level', '1', 'Platformer', 'Side-scrolling platformer with collection elements.', 'Find the gold and help Fievel reunite with his family.', 'Join the brave mouse Fievel in an adventure across the American frontier.', 'An American Tail - Fievel''s Gold Rush is a charming platformer based on the classic film. Navigate through diverse levels from New York to the West, collect gold, and avoid treacherous cats in this family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('an-american-tail---fievels-gold-rush-utrashman', 'GAMEBOYADVANCE', 'An American Tail - Fievel''s Gold Rush (U)(TrashMan)', '2002', 'Platform', '7th Level', '1', 'Platformer', 'Side-scrolling platformer with collection elements.', 'Find the gold and help Fievel reunite with his family.', 'Join the brave mouse Fievel in an adventure across the American frontier.', 'The US version of Fievel''s Gold Rush features the same heartwarming story and solid 2D platforming. Explore iconic movie locations and master various environmental puzzles in this polished handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angel-collection---mezase!-gakuen-no-fashion-leader-jpatience', 'GAMEBOYADVANCE', 'Angel Collection - Mezase! Gakuen no Fashion Leader (J)(Patience)', '2002', 'Fashion', 'Ask Kodansha', '1', 'Lifestyle', 'Fashion simulation and social adventure.', 'Become the school''s fashion leader and master style trends.', 'A stylish Japanese simulation focusing on school life and fashion.', 'Angel Collection allows players to explore school life through the lens of fashion. Coordinate outfits, participate in style competitions, and build relationships to become the most fashionable student in the academy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angel-collection-2---pichimo-ni-narou-jcaravan', 'GAMEBOYADVANCE', 'Angel Collection 2 - Pichimo ni Narou (J)(Caravan)', '2003', 'Fashion', 'Ask Kodansha', '1', 'Lifestyle', 'Fashion simulation and modeling adventure.', 'Win modeling contests and become a top fashion idol.', 'The sequel to the Japanese fashion hit with more styles and contests.', 'Angel Collection 2 expands on the original''s fashion mechanics. Engage in new modeling challenges, unlock a wider variety of clothing items, and climb the ranks of the fashion world in this colorful Japanese simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelic-layer-jindependent', 'GAMEBOYADVANCE', 'Angelic Layer (J)(Independent)', '2001', 'Action', 'Bones', '1', 'Action Fighting', 'Strategy-based battle system with doll customization.', 'Win the Angelic Layer tournament by commanding your doll.', 'A tactical battle game based on the popular manga and anime.', 'Angelic Layer for GBA features a unique combat system where you customize your "Angel" doll. Strategize your moves, upgrade your stats, and defeat rivals in the tournament arena in this faithful adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('angelique-jcezar', 'GAMEBOYADVANCE', 'Angelique (J)(Cezar)', '2002', 'Simulation', 'Koei', '1', 'Dating Simulation', 'Visual novel and social simulation.', 'Build relationships and become the next Queen of the universe.', 'A classic Japanese otome game featuring deep storytelling and romance.', 'Angelique brings the pioneer of the otome genre to GBA. Manage your daily schedule, interact with the Guardians, and make pivotal choices that influence your path to the throne and your romantic interests.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-mania-jrapid-fire', 'GAMEBOYADVANCE', 'Animal Mania (J)(Rapid Fire)', '2003', 'Educational', 'Interlink', '1', 'Educational', 'Animal care and mini-game collection.', 'Manage a variety of animals and keep them happy.', 'A cute Japanese simulation game focused on animal interaction.', 'Animal Mania offers players a chance to care for a wide range of adorable creatures. Complete tasks, play mini-games, and maintain your animal sanctuary in this relaxing and family-friendly handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-snap---rescue-them-2-by-2-eindependent', 'GAMEBOYADVANCE', 'Animal Snap - Rescue Them 2 By 2 (E)(Independent)', '2003', 'Puzzle', 'Torus Games', '1', 'Puzzle', 'Tile-matching puzzle and collection gameplay.', 'Match animal pairs to rescue them before time runs out.', 'A fun and educational puzzle game featuring various animals.', 'Animal Snap - Rescue Them 2 By 2 is an addictive matching game. Race against the clock to find pairs, unlock new animal facts, and save creatures in this vibrant and engaging handheld puzzle experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-snap---rescue-them-2-by-2-uindependent', 'GAMEBOYADVANCE', 'Animal Snap - Rescue Them 2 By 2 (U)(Independent)', '2003', 'Puzzle', 'Torus Games', '1', 'Puzzle', 'Tile-matching puzzle and collection gameplay.', 'Match animal pairs to rescue them before time runs out.', 'A fun and educational puzzle game featuring various animals.', 'The US version of Animal Snap offers the same engaging puzzle mechanics. With multiple difficulty levels and a charming art style, it’s a perfect pick for puzzle fans looking for quick and rewarding gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-yokochou---doki-doki-kyushutsu-daisakusen-no-maki-jindependent', 'GAMEBOYADVANCE', 'Animal Yokochou - Doki Doki Kyushutsu Daisakusen No Maki (J)(Independent)', '2005', 'Adventure', 'Independent', '1', 'Adventure', 'Mini-game collection and adventure platforming.', 'Complete various missions with the Animal Yokochou crew.', 'A wacky and colorful Japanese adventure with animal friends.', 'Animal Yokochou - Doki Doki Kyushutsu Daisakusen is based on the comedy series. Engage in bizarre and funny mini-games, explore the neighborhood, and interact with the strange animal inhabitants in this high-energy title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animal-yokochou---doki-doki-shinkyuu-shiken!-no-kan-jcaravan', 'GAMEBOYADVANCE', 'Animal Yokochou - Doki Doki Shinkyuu Shiken! no Kan (J)(Caravan)', '2005', 'Adventure', 'Caravan', '1', 'Adventure', 'Mini-game collection and school-themed challenges.', 'Pass the school exams through various mini-game tasks.', 'More wacky animal antics in this Japanese school-themed sequel.', 'Doki Doki Shinkyuu Shiken! continues the humor of the series. Players must complete a variety of school-themed challenges and puzzles to advance their grade, all while enjoying the trademark chaos of Animal Yokochou.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs---hollywood-hypnotics-prototype', 'GAMEBOYADVANCE', 'Animaniacs - Hollywood Hypnotics (Prototype)', '2000', 'Platform', 'Konami', '1', 'Platformer', 'Side-scrolling action platformer.', 'Stop the hypnotics and save the Hollywood movie studios.', 'Help Yakko, Wakko, and Dot in this unreleased cartoon adventure.', 'Animaniacs - Hollywood Hypnotics is a fascinating prototype that captures the spirit of the show. Navigate the Warner Bros. lot, use character-specific abilities, and stop the hypnotic plan in this rare piece of GBA history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animaniacs---lights-camera-action-etrashman', 'GAMEBOYADVANCE', 'Animaniacs - Lights, Camera, Action (E)(Trashman)', '2001', 'Platform', 'Warthog Games', '1', 'Platformer', 'Isometric action-adventure and mini-game collection.', 'Stop the Director and complete various movie-themed levels.', 'Join the Animaniacs in a wacky quest across movie sets.', 'Animaniacs - Lights, Camera, Action! features isometric exploration and various mini-games. Play as the three Warner siblings, solve environmental puzzles, and cause chaos on the film sets to stop the evil antagonist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('animon', 'GAMEBOYADVANCE', 'ANIMON', '2005', 'Action', 'Independent', '1', 'Action', 'Creature collection and turn-based battle RPG.', 'Collect and train monsters to become the ultimate trainer.', 'A creative fan-made reimagining of creature-catching mechanics.', 'ANIMON is a unique project that blends classic RPG exploration with fresh monster designs. Navigate a vibrant world, build your team, and master the elemental battle system in this engaging handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('antz-extreme-racing-evenom', 'GAMEBOYADVANCE', 'Antz Extreme Racing (E)(Venom)', '2002', 'Racing', 'Motorola Games', '1', 'Arcade Racing', 'Kart racing and vehicular combat.', 'Win the ultimate insect racing championship.', 'High-speed racing action featuring the characters from the Antz movie.', 'Antz Extreme Racing brings the tiny world of ants to the racetrack. Drive diverse vehicles across garden and city tracks, use bug-themed power-ups, and compete for the trophy in this fast-paced arcade racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('antz-extreme-racing-uindependent', 'GAMEBOYADVANCE', 'Antz Extreme Racing (U)(Independent)', '2002', 'Racing', 'Motorola Games', '1', 'Arcade Racing', 'Kart racing and vehicular combat.', 'Win the ultimate insect racing championship.', 'High-speed racing action featuring the characters from the Antz movie.', 'The US version of Antz Extreme Racing delivers competitive racing for all ages. Choose your favorite character, master the drift mechanics, and navigate oversized environments in this fun and accessible handheld racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aozoora-to-nakamatachi---yume-no-bouken-jmegaroms', 'GAMEBOYADVANCE', 'Aozoora to Nakamatachi - Yume no Bouken (J)(Megaroms)', '2003', 'Adventure', 'Megaroms', '1', 'Adventure', '2D side-scrolling platformer with adventure elements.', 'Navigate magical worlds and defeat various enemies.', 'A charming Japanese platformer featuring a magical sky adventure.', 'Aozoora to Nakamatachi brings a vibrant fantasy world to the GBA. Control your hero through challenging levels, use unique abilities to overcome obstacles, and discover hidden secrets in this polished 2D adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('archer-macleans-3d-pool-urising-sun', 'GAMEBOYADVANCE', 'Archer Maclean''s 3D Pool (U)(Rising Sun)', '2002', 'Sports', 'Archer Maclean', '2', 'Pool', 'First-person perspective billiards simulation.', 'Clear the table and win professional pool tournaments.', 'A realistic 3D pool experience with impressive physics.', 'Archer Maclean''s 3D Pool for GBA delivers an incredibly immersive billiards simulation. Featuring a unique 3D engine, players can master bank shots, spin, and precision angles in various game modes, from quick practice to intense championship tournaments.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arctic-tale-usir-vg', 'GAMEBOYADVANCE', 'Arctic Tale (U)(Sir VG)', '2007', 'Adventure', 'Artificial Mind & Movement', '1', 'Adventure', 'Animal-themed exploration and survival mini-games.', 'Survive the harsh arctic environments and protect your family.', 'A charming journey through the arctic based on the hit documentary.', 'Arctic Tale for GBA lets you experience the life of a polar bear and a walrus. Navigate the freezing wilderness, participate in educational mini-games, and learn about the delicate ecosystem in this visually pleasing and family-friendly adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('aria-of-sorrow-magician-mode', 'GAMEBOYADVANCE', 'Aria of Sorrow Magician Mode', '2003', 'Hack', 'Independent', '1', 'ROM Hack', 'Side-scrolling action-RPG (Metroidvania) with magic focus.', 'Defeat the chaos within the castle using advanced magic.', 'A special unlockable mode for the legendary Aria of Sorrow.', 'Aria of Sorrow Magician Mode changes the classic gameplay by giving the player access to all magic spells from the start. Explore Dracula''s castle with a focus on MP management and elemental attacks in this challenging and strategic variant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---operation-green-umenace', 'GAMEBOYADVANCE', 'Army Men - Operation Green (U)(Menace)', '2001', 'Action', '3DO Company', '1', 'Action Shooter', 'Isometric tactical shooting and combat action.', 'Lead the Green Army to victory against the Tan menace.', 'High-stakes plastic soldier warfare in a variety of environments.', 'Army Men: Operation Green brings the classic toy soldier battles to your handheld. Control your units through five massive environments, use diverse weaponry, and complete tactical objectives to ensure the Green Army''s global dominance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men---turf-wars-umode7', 'GAMEBOYADVANCE', 'Army Men - Turf Wars (U)(Mode7)', '2002', 'Action', '3DO Company', '1', 'Action Shooter', 'Isometric tactical shooting and combat action.', 'Defeat the Tan Army and protect your territory from invasion.', 'Intense squad-based combat featuring the iconic plastic soldiers.', 'Army Men: Turf Wars features fast-paced isometric action. Command your troops through urban and wilderness maps, utilizing vehicles and specialized weapons to thwart the Tan Army''s plans in this high-energy handheld combat title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('army-men-advance-ueurasia', 'GAMEBOYADVANCE', 'Army Men Advance (U)(Eurasia)', '2001', 'Action', '3DO Company', '1', 'Action Shooter', 'Top-down tactical shooter and action-adventure.', 'Complete specialized military missions behind enemy lines.', 'The classic plastic soldier experience in a top-down format.', 'Army Men Advance puts you in control of Sarge or Vikki. Navigate through 12 challenging levels, from the kitchen to the battlefield, using classic toy weapons to defeat the Tan forces in this nostalgia-driven GBA action game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('around-the-world-in-80-days-eindependent', 'GAMEBOYADVANCE', 'Around The World In 80 Days (E)(Independent)', '2004', 'Adventure', 'Saffire', '1', 'Adventure', 'Side-scrolling platformer with puzzle elements.', 'Travel across the globe in 80 days to win the famous bet.', 'Embark on a grand Victorian adventure based on the classic novel.', 'Around The World In 80 Days for GBA captures the spirit of Jules Verne''s masterpiece. Help Phileas Fogg and Passepartout navigate diverse levels in London, India, and beyond, solving puzzles and overcoming obstacles to beat the clock.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('around-the-world-in-80-days-uvenom', 'GAMEBOYADVANCE', 'Around The World In 80 Days (U)(Venom)', '2004', 'Adventure', 'Saffire', '1', 'Adventure', 'Side-scrolling platformer with puzzle elements.', 'Travel across the globe in 80 days to win the famous bet.', 'Embark on a grand Victorian adventure based on the classic novel.', 'The US version of Around The World In 80 Days features the same globe-trotting action. Master challenging platforming segments and use unique character abilities to ensure the duo arrives back in London on time to win the wager.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur-and-the-invisibles-usir-vg', 'GAMEBOYADVANCE', 'Arthur and the Invisibles (U)(Sir VG)', '2007', 'Action', 'Magic Pockets', '1', 'Action Adventure', 'Action-adventure with combat and exploration.', 'Save the Minimoys'' world from the evil Malthazar.', 'Shrink down for a giant adventure in this movie-based game.', 'Arthur and the Invisibles for GBA combines exploration and combat. Play as Arthur, Selenia, and Betameche, utilizing their unique skills to solve puzzles and fight enemies in a beautifully rendered miniature world based on the Luc Besson film.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('arthur-and-the-minimoys-efirex', 'GAMEBOYADVANCE', 'Arthur And The Minimoys (E)(FireX)', '2007', 'Action', 'Magic Pockets', '1', 'Action Adventure', 'Action-adventure with combat and exploration.', 'Save the Minimoys'' world from the evil Malthazar.', 'Shrink down for a giant adventure in this movie-based game.', 'Arthur And The Minimoys (European Version) offers a faithful adaptation of the fantasy adventure. Experience high-speed racing segments and intense boss battles as you fight to protect the underground kingdom from the forces of evil.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ashita-no-joe-jrising-sun', 'GAMEBOYADVANCE', 'Ashita No Joe (J)(Rising Sun)', '2002', 'Sports', 'Wave Master', '1', 'Boxing', 'Side-scrolling boxing and action simulation.', 'Rise through the ranks of professional boxing to become a champion.', 'A hard-hitting boxing game based on the legendary manga.', 'Ashita No Joe for GBA brings the intensity of Joe Yabuki''s story to life. Master the art of the jab, hook, and counter-punch in detailed 2D boxing matches that capture the dramatic spirit and visual style of the iconic anime.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-&-obelix---paf!-them-all!-emenace', 'GAMEBOYADVANCE', 'Asterix & Obelix - PAF! Them All! (E)(Menace)', '2002', 'Action', 'Bit Managers', '1', 'Action Platformer', 'Beat ''em up and side-scrolling action platformer.', 'Defeat the Roman legions and protect the Gaulish village.', 'Bash the Romans with Asterix and Obelix in this colorful brawler.', 'Asterix & Obelix - PAF! Them All! is a vibrant beat ''em up that feels like a comic book in motion. Take control of the legendary duo, use super-strength attacks, and clear multiple levels of Roman enemies in this high-energy handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('asterix-and-obelix-xxl-erising-sun', 'GAMEBOYADVANCE', 'Asterix and Obelix XXL (E)(Rising Sun)', '2003', 'Action', 'Étranges Libellules', '1', 'Action Platformer', '3D-style platforming and action-adventure.', 'Free the kidnapped villagers and stop Caesar''s latest plot.', 'A massive adventure featuring the world''s most famous Gauls.', 'Asterix and Obelix XXL for GBA offers impressive pseudo-3D graphics and fast-paced action. Travel across the Roman Empire, solve environmental puzzles, and engage in massive brawls against hundreds of Romans in this ambitious handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-boy---omega-factor-eendless-piracy', 'GAMEBOYADVANCE', 'Astro Boy - Omega Factor (E)(Endless Piracy)', '2004', 'Action', 'Treasure', '1', 'Action Platformer', 'Side-scrolling beat ''em up and shoot ''em up hybrid.', 'Defeat the evil robot forces and uncover your hidden potential.', 'A masterpiece of action gaming from the legendary studio Treasure.', 'Astro Boy: Omega Factor is widely considered one of the best GBA games. Featuring a deep story, incredible pixel art, and a complex combat system that rewards exploration, it is a definitive tribute to Osamu Tezuka''s iconic hero.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-boy---omega-factor-uvenom', 'GAMEBOYADVANCE', 'Astro Boy - Omega Factor (U)(Venom)', '2004', 'Action', 'Treasure', '1', 'Action Platformer', 'Side-scrolling beat ''em up and shoot ''em up hybrid.', 'Defeat the evil robot forces and uncover your hidden potential.', 'A masterpiece of action gaming from the legendary studio Treasure.', 'Astro Boy: Omega Factor (US Version) delivers the same high-octane action. Master the EX gauges to unleash screen-clearing attacks and traverse through beautifully designed levels in this essential handheld action-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('astro-boy---tetsuwan-atom-jeurasia', 'GAMEBOYADVANCE', 'Astro Boy - Tetsuwan Atom (J)(Eurasia)', '2003', 'Action', 'Treasure', '1', 'Action Platformer', 'Side-scrolling beat ''em up and shoot ''em up hybrid.', 'Defeat the evil robot forces and uncover your hidden potential.', 'A masterpiece of action gaming from the legendary studio Treasure.', 'Astro Boy: Tetsuwan Atom is the original Japanese release of Omega Factor. Experience the epic origin story of the mighty robot boy, featuring intense boss battles and the innovative "Omega Factor" character-linking system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-anniversary-advance-eindependent', 'GAMEBOYADVANCE', 'Atari Anniversary Advance (E)(Independent)', '2001', 'Compilation', 'Digital Eclipse', '1', 'Classic Arcade', 'Classic arcade compilation and retro simulation.', 'Achieve high scores and relive the golden age of Atari.', 'A collection of legendary Atari hits like Centipede and Missile Command.', 'Atari Anniversary Advance brings the arcade home. Enjoy pixel-perfect ports of iconic titles, including Asteroids and Battlezone, along with trivia and historical photos that make this the ultimate retro package for GBA owners.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atari-anniversary-advance-umode7', 'GAMEBOYADVANCE', 'Atari Anniversary Advance (U)(Mode7)', '2001', 'Compilation', 'Digital Eclipse', '1', 'Classic Arcade', 'Classic arcade compilation and retro simulation.', 'Achieve high scores and relive the golden age of Atari.', 'A collection of legendary Atari hits like Centipede and Missile Command.', 'The US version of Atari Anniversary Advance features the same classic lineup. Test your skills in Tempest and Super Breakout, and see how your scores compare to the legends of the 1980s arcade scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atlantis---the-lost-empire-elightforce', 'GAMEBOYADVANCE', 'Atlantis - The Lost Empire (E)(Lightforce)', '2001', 'Adventure', 'Disney Interactive', '1', 'Adventure', 'Side-scrolling action platformer with exploration.', 'Find the Heart of Atlantis and save the underwater city.', 'Join Milo and the crew in this Disney movie-based adventure.', 'Atlantis: The Lost Empire for GBA lets you control multiple characters from the film. Navigate dangerous caves, solve mechanical puzzles, and fight off guardians to discover the secrets of the legendary lost continent.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atlantis---the-lost-empire-ueurasia', 'GAMEBOYADVANCE', 'Atlantis - The Lost Empire (U)(Eurasia)', '2001', 'Adventure', 'Disney Interactive', '1', 'Adventure', 'Side-scrolling action platformer with exploration.', 'Find the Heart of Atlantis and save the underwater city.', 'Join Milo and the crew in this Disney movie-based adventure.', 'The US version of Atlantis: The Lost Empire delivers a cinematic experience on your GBA. Use unique character abilities to bypass traps and explore the beautifully animated environments of the subterranean world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atomic-betty-utrashman', 'GAMEBOYADVANCE', 'Atomic Betty (U)(Trashman)', '2005', 'Action', 'Big Blue Bubble', '1', 'Action Adventure', 'Side-scrolling action platformer and shoot ''em up.', 'Protect the galaxy from the villainous Baron Vain.', 'Galactic adventure with Betty and the Galactic Guardians.', 'Atomic Betty for GBA brings the hit animated show to your pocket. Switch between Betty''s gadgets, Sparky''s pilot skills, and X-5''s technical expertise to complete missions and save the universe from alien threats.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv---quad-power-racing-ueurasia', 'GAMEBOYADVANCE', 'ATV - Quad Power Racing (U)(Eurasia)', '2002', 'Racing', 'Climax Racing', '1', 'Arcade Racing', 'Off-road arcade racing and stunt driving.', 'Win the quad racing world championship across various terrains.', 'High-speed ATV action with a focus on big air and stunts.', 'ATV: Quad Power Racing delivers intense off-road competition. Master the physics of your quad bike to perform tricks, manage your speed on muddy tracks, and outpace the competition in this fast-paced GBA racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv---thunder-ridge-riders-usir-vg', 'GAMEBOYADVANCE', 'ATV - Thunder Ridge Riders (U)(Sir VG)', '2003', 'Racing', 'Climax Racing', '1', 'Arcade Racing', 'Off-road arcade racing and stunt driving.', 'Navigate rugged mountain tracks and finish first.', 'Extreme quad bike racing through treacherous ridge environments.', 'ATV: Thunder Ridge Riders features challenging outdoor circuits. Battle against the elements and other riders in a quest for the top spot, utilizing a robust physics engine and responsive controls designed for handheld play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('atv-thunder-ridge-riders-esupplex', 'GAMEBOYADVANCE', 'ATV Thunder Ridge Riders (E)(sUppLeX)', '2003', 'Racing', 'Climax Racing', '1', 'Arcade Racing', 'Off-road arcade racing and stunt driving.', 'Navigate rugged mountain tracks and finish first.', 'Extreme quad bike racing through treacherous ridge environments.', 'The European version of ATV Thunder Ridge Riders offers the same gritty racing experience. Tune your vehicle for different track conditions and prove your skills in the mud and dirt of Thunder Ridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avatar---the-last-airbender---the-burning-earth-usir-vg', 'GAMEBOYADVANCE', 'Avatar - The Last Airbender - The Burning Earth (U)(Sir VG)', '2007', 'Action', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with combat and elemental puzzles.', 'Stop the Fire Nation and master the four elements.', 'Lead Aang and his friends in this epic series-based adventure.', 'Avatar: The Burning Earth for GBA follows the story of Book 2. Engage in intense elemental combat, solve environmental puzzles using bending, and face off against Azula and the Dai Li in this faithful animated adaptation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avatar---the-last-airbender-urising-sun', 'GAMEBOYADVANCE', 'Avatar - The Last Airbender (U)(Rising Sun)', '2006', 'Action', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with combat and elemental puzzles.', 'Begin your journey to master the elements and defeat the Fire Lord.', 'The first GBA adventure based on the legendary Nickelodeon show.', 'Avatar: The Last Airbender lets you control Aang, Katara, Sokka, and Haru. Master unique bending styles to defeat enemies and solve intricate puzzles as you travel through the Four Nations to save the world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avatar---the-legend-of-aang---the-burning-earth-esir-vg', 'GAMEBOYADVANCE', 'Avatar - The Legend of Aang - The Burning Earth (E)(Sir VG)', '2007', 'Action', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with combat and elemental puzzles.', 'Stop the Fire Nation and master the four elements.', 'Lead Aang and his friends in this epic series-based adventure.', 'The Legend of Aang: The Burning Earth features the same high-stakes bending action. Enhance your abilities, explore iconic locations from the show, and protect the world from the Fire Nation''s expansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('avatar---the-legend-of-aang-esir-vg', 'GAMEBOYADVANCE', 'Avatar - The Legend of Aang (E)(Sir VG)', '2006', 'Action', 'THQ Studio Australia', '1', 'Action Adventure', 'Action-adventure with combat and elemental puzzles.', 'Begin your journey to master the elements and defeat the Fire Lord.', 'The first GBA adventure based on the legendary Nickelodeon show.', 'The Legend of Aang (European Release) brings the magic of the Four Nations to life. Experience the story of Book 1, mastering airbending and gathering allies to restore balance to a fractured world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('azumanga-daioh-advance-jmugs', 'GAMEBOYADVANCE', 'Azumanga Daioh Advance (J)(Mugs)', '2003', 'Simulation', 'King Records', '1', 'Life Simulation', 'Mini-game collection and social simulation.', 'Complete various school tasks and wacky mini-games.', 'Join the Azumanga Daioh crew in this delightful Japanese school-life game.', 'Azumanga Daioh Advance is a charming title for fans of the comedy series. Participate in a variety of bizarre and funny mini-games based on iconic moments from the anime, all featuring the show''s signature humor and art style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b-densetsu!-battle-b-daman-moero!-b-kon-jcaravan', 'GAMEBOYADVANCE', 'B-Densetsu! Battle B-Daman Moero! B-Kon (J)(Caravan)', '2003', 'Action', 'Takara', '1', 'Action Arena', 'Tactical marble-shooting and combat simulation.', 'Win the B-Daman tournament and become the top player.', 'Intense marble-blasting action based on the popular toy line.', 'B-Densetsu! Battle B-Daman features a deep customization system for your B-Daman robots. Strategize your shots, upgrade your parts, and defeat rivals in fast-paced arena battles in this engaging Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('b-legend!-battle-b-daman-fire-spirit-jsupplex', 'GAMEBOYADVANCE', 'B-Legend! Battle B-Daman Fire Spirit (J)(sUppLeX)', '2004', 'Action', 'Takara', '1', 'Action Arena', 'Tactical marble-shooting and combat simulation.', 'Win the B-Daman tournament and become the top player.', 'Intense marble-blasting action based on the popular toy line.', 'B-Legend! Battle B-Daman Fire Spirit is the high-octane sequel featuring new parts and characters. Master the fire spirit abilities to dominate the competition and prove you are the ultimate B-Daman master.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('babar---to-the-rescue-erising-sun', 'GAMEBOYADVANCE', 'Babar - To the Rescue (E)(Rising Sun)', '2001', 'Adventure', 'Planet Interactive', '1', 'Adventure', 'Educational side-scrolling platformer.', 'Help Babar the Elephant rescue his friends and protect the kingdom.', 'A gentle and colorful adventure featuring the beloved King of Elephants.', 'Babar - To the Rescue for GBA is a family-friendly platformer designed for younger players. Navigate through vibrant levels, solve simple environmental puzzles, and experience the charm of the classic children''s book series on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('babar---to-the-rescue-utrashman', 'GAMEBOYADVANCE', 'Babar - To the Rescue (U)(Trashman)', '2001', 'Adventure', 'Planet Interactive', '1', 'Adventure', 'Educational side-scrolling platformer.', 'Help Babar the Elephant rescue his friends and protect the kingdom.', 'A gentle and colorful adventure featuring the beloved King of Elephants.', 'Babar - To the Rescue (US Version) brings the heartwarming world of Babar to the GBA. Explore Celesteville, overcome obstacles with trunk-based abilities, and enjoy a safe, engaging gaming experience perfect for early gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-stone-eindependent', 'GAMEBOYADVANCE', 'Back To Stone (E)(Independent)', '2001', 'Puzzle', 'Spiral House', '1', 'Puzzle', 'Isometric action-adventure with combat and puzzles.', 'Reclaim your kingdom from dark forces after being turned to stone.', 'A dark fantasy epic featuring unique isometric combat and exploration.', 'Back To Stone is a hidden gem for GBA. Control a hero with the power to transform enemies into stone, using them as platforms or tools to solve intricate puzzles while fighting through a beautifully detailed isometric world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('back-to-stone-urising-sun', 'GAMEBOYADVANCE', 'Back to Stone (U)(Rising Sun)', '2001', 'Puzzle', 'Spiral House', '1', 'Puzzle', 'Isometric action-adventure with combat and puzzles.', 'Reclaim your kingdom from dark forces after being turned to stone.', 'A dark fantasy epic featuring unique isometric combat and exploration.', 'Back to Stone (US Version) delivers a challenging blend of action and strategy. Master the stone-transformation mechanic to navigate complex dungeons and defeat powerful bosses in this atmospheric fantasy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backtrack-umode7', 'GAMEBOYADVANCE', 'Backtrack (U)(Mode7)', '2001', 'Action', 'Vicarious Visions', '1', 'Action Shooter', 'First-person shooter (FPS) with corridor exploration.', 'Eliminate the alien threat and find the exit of each lunar base.', 'A retro-style FPS that pushes the GBA hardware with 3D environments.', 'Backtrack brings classic corridor-shooting action to the GBA. Navigate through 12 intense levels on a moon base, utilizing a variety of futuristic weapons to stop an alien invasion in this fast-paced, portable first-person experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-baseball-uvenom', 'GAMEBOYADVANCE', 'Backyard Baseball (U)(Venom)', '2001', 'Sports', 'Humongous Entertainment', '1', 'Baseball', 'Arcade-style sports simulation with power-ups.', 'Win the Backyard World Series with a team of neighborhood kids.', 'Play baseball with the Backyard Gang and kid versions of MLB pros.', 'Backyard Baseball for GBA captures the fun of sandlot ball. Draft your favorite characters, including "Secret Weapon" Pablo Sanchez, and use wacky power-ups to hit home runs and dominate the neighborhood leagues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-baseball-2006-utrashman', 'GAMEBOYADVANCE', 'Backyard Baseball 2006 (U)(TrashMan)', '2005', 'Sports', 'Humongous Entertainment', '1', 'Baseball', 'Arcade-style sports simulation with power-ups.', 'Climb the rankings to win the championship trophy.', 'The 2006 edition of the hit baseball series with updated rosters.', 'Backyard Baseball 2006 features improved graphics and even more kid-sized pros. Experience accessible, fun-to-play baseball mechanics that focus on timing and strategy rather than complex simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-football-umode7', 'GAMEBOYADVANCE', 'Backyard Football (U)(Mode7)', '2001', 'Sports', 'Humongous Entertainment', '1', 'Football', 'Arcade-style American football simulation.', 'Lead your team of kids to victory in the Cereal Bowl.', 'High-energy 7-on-7 football with power-ups and crazy plays.', 'Backyard Football brings gridiron action to your pocket. Pick your team, execute trick plays, and utilize special power-ups like "Sonic Boom" to outrun the defense and score touchdowns in this portable sports hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-football-2006-utrashman', 'GAMEBOYADVANCE', 'Backyard Football 2006 (U)(Trashman)', '2005', 'Sports', 'Humongous Entertainment', '1', 'Football', 'Arcade-style American football simulation.', 'Win the ultimate championship with your custom kid team.', 'Fun, fast-paced football featuring kid versions of NFL superstars.', 'Backyard Football 2006 offers a deeper season mode and updated NFL players in their kid forms. Master the passing and running game with simple controls designed for maximum handheld fun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-hockey-urising-sun', 'GAMEBOYADVANCE', 'Backyard Hockey (U)(Rising Sun)', '2002', 'Sports', 'Humongous Entertainment', '1', 'Hockey', 'Arcade-style ice hockey simulation.', 'Outscore your opponents on the ice to win the cup.', 'Fast-paced hockey action with neighborhood kids and NHL stars.', 'Backyard Hockey brings the intensity of the rink to GBA. Features 3-on-3 action, power-ups, and a deep season mode where you can customize your team to become the kings of the neighborhood ice.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-skateboarding-utrashman', 'GAMEBOYADVANCE', 'Backyard Skateboarding (U)(Trashman)', '2002', 'Sports', 'Humongous Entertainment', '1', 'Skateboarding', 'Extreme sports skating with trick-based challenges.', 'Master the half-pipe and urban spots to become a skate legend.', 'Skate through the neighborhood and perform big tricks as a kid.', 'Backyard Skateboarding lets you grind, kickflip, and ollie through diverse urban levels. Unlock new gear, complete trick objectives, and skate alongside kid versions of pro skaters in this accessible extreme sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-sports-baseball-2007-utrashman', 'GAMEBOYADVANCE', 'Backyard Sports Baseball 2007 (U)(Trashman)', '2006', 'Sports', 'Humongous Entertainment', '1', 'Baseball', 'Arcade-style sports simulation with power-ups.', 'Win the championship in the definitive 2007 season.', 'The classic backyard ball game with 2007''s best rosters.', 'Backyard Sports Baseball 2007 offers the most refined baseball gameplay in the series. Manage your lineup and use special abilities to win every game in this colorful, high-energy sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-sports-basketball-2007-urising-sun', 'GAMEBOYADVANCE', 'Backyard Sports Basketball 2007 (U)(Rising Sun)', '2006', 'Sports', 'Humongous Entertainment', '1', 'Basketball', 'Arcade-style basketball simulation with dunks and triples.', 'Dominate the court and win the neighborhood tournament.', 'High-flying hoops action with the Backyard kids and NBA pros.', 'Backyard Sports Basketball 2007 features fast-paced court action. Use power-ups to perform gravity-defying dunks and master the three-point line in this fun, accessible take on professional basketball.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('backyard-sports-football-2007-urising-sun', 'GAMEBOYADVANCE', 'Backyard Sports Football 2007 (U)(Rising Sun)', '2006', 'Sports', 'Humongous Entertainment', '1', 'Football', 'Arcade-style American football simulation.', 'Lead your neighborhood team to a perfect season.', 'Strategic but fun football action with kid-sized NFL legends.', 'Backyard Sports Football 2007 delivers the final GBA entry in the series. Featuring polished 7-on-7 gameplay, deep stat tracking, and all the wacky power-ups fans love, it''s the ultimate handheld football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakunetsu-dodge-ball-fighters-jcapital', 'GAMEBOYADVANCE', 'Bakunetsu Dodge Ball Fighters (J)(Capital)', '2001', 'Action', 'Atlus', '1', 'Action Sports', 'Fast-paced dodgeball combat and sports action.', 'Defeat rival teams and become the dodgeball champions.', 'A high-energy Japanese dodgeball game with special attacks.', 'Bakunetsu Dodge Ball Fighters features intense arena battles. Use character-specific "super shots" to knock out your opponents in this arcade-style sports title that emphasizes timing and strategy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakuten-shoot-beyblade---gekitou!-saikyou-blade-jindependent', 'GAMEBOYADVANCE', 'Bakuten Shoot Beyblade - Gekitou! Saikyou Blade (J)(Independent)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Tactical spinning-top combat and simulation.', 'Win the Beyblade tournament and defeat rival bladers.', 'The first GBA entry for the massive Beyblade franchise.', 'Bakuten Shoot Beyblade - Gekitou! Saikyou Blade lets you customize your top and engage in strategic arena battles. Master the "Bit Beast" powers to outlast and out-spin your competition in this Japanese hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakuten-shoot-beyblade-2002-team-battle!-daichi-hen-jparanoid', 'GAMEBOYADVANCE', 'Bakuten Shoot Beyblade 2002 Team Battle! Daichi Hen (J)(Paranoid)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Tactical spinning-top combat and simulation.', 'Lead Daichi to victory in the team battle world championship.', 'A team-based Beyblade adventure featuring Daichi''s story arc.', 'Bakuten Shoot Beyblade 2002: Daichi Hen focuses on the 2002 season. Build a balanced team, customize your Beyblades with new parts, and climb the ranks in this deep, story-driven tactical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bakuten-shoot-beyblade-2002-team-battle!-takao-hen-jparanoid', 'GAMEBOYADVANCE', 'Bakuten Shoot Beyblade 2002 Team Battle! Takao Hen (J)(Paranoid)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Tactical spinning-top combat and simulation.', 'Follow Takao''s journey to win the team battle tournament.', 'The companion game to Daichi Hen, focusing on the protagonist Takao.', 'Bakuten Shoot Beyblade 2002: Takao Hen offers a unique perspective on the team battle series. Manage your team''s stats, choose the right parts for your Beyblade, and master the art of the spin.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baldurs-gate---dark-alliance-ecezar', 'GAMEBOYADVANCE', 'Baldur''s Gate - Dark Alliance (E)(Cezar)', '2004', 'RPG', 'Snowblind Studios', '1', 'Action RPG', 'Isometric hack-and-slash action-RPG.', 'Save the city of Baldur''s Gate and stop the dark alliance.', 'A massive fantasy RPG experience based on Dungeons & Dragons.', 'Baldur''s Gate: Dark Alliance for GBA is a technical marvel. Explore vast dungeons, upgrade your character''s skills, and loot powerful weapons in this deep, atmospheric action-RPG that faithfully captures the spirit of the console original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baldurs-gate---dark-alliance-uhyperion', 'GAMEBOYADVANCE', 'Baldurs Gate - Dark Alliance (U)(Hyperion)', '2004', 'RPG', 'Snowblind Studios', '1', 'Action RPG', 'Isometric hack-and-slash action-RPG.', 'Save the city of Baldur''s Gate and stop the dark alliance.', 'A massive fantasy RPG experience based on Dungeons & Dragons.', 'Baldurs Gate: Dark Alliance (US Version) delivers intense dungeon-crawling action. Choose your class, master magical spells or brutal combat, and uncover a dark conspiracy in this top-tier GBA role-playing game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballistic---ecks-vs-sever-uvenom', 'GAMEBOYADVANCE', 'Ballistic - Ecks vs. Sever (U)(Venom)', '2001', 'Action', 'Vicarious Visions', '1', 'Action Shooter', 'First-person shooter (FPS) with mission-based objectives.', 'Complete high-stakes espionage missions as Ecks or Sever.', 'A groundbreaking FPS for GBA featuring smooth 3D environments.', 'Ballistic: Ecks vs. Sever is an impressive technical achievement. Based on the film, it offers intense gunplay, various mission types, and a fluid framerate that sets a high bar for first-person action on a handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ballistic---ecks-vs-sever-2-epatience', 'GAMEBOYADVANCE', 'Ballistic - Ecks vs. Sever 2 (E)(Patience)', '2002', 'Action', 'Vicarious Visions', '1', 'Action Shooter', 'First-person shooter (FPS) with mission-based objectives.', 'Stop the global threat and survive the duel between agents.', 'The high-octane sequel with improved graphics and larger levels.', 'Ballistic: Ecks vs. Sever 2 expands the FPS experience on GBA. Featuring more weapons, complex mission structures, and refined controls, it provides a gritty and immersive spy thriller experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie---la-vendetta-di-grunty-itrashman', 'GAMEBOYADVANCE', 'Banjo Kazooie - La vendetta di Grunty (I)(TrashMan)', '2003', 'Platform', 'Rare', '1', 'Platformer', 'Isometric 3D platformer and collection adventure.', 'Stop Gruntilda''s ghost from building a robotic body.', 'Join Banjo and Kazooie in this Italian-localized GBA adventure.', 'Banjo-Kazooie: La vendetta di Grunty brings the N64 charm to GBA. Collect Jiggies and Notes, learn new transformations from Mumbo Jumbo, and defeat the witch''s minions in this beautifully rendered isometric platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie-gruntys-revenge-esuxxors', 'GAMEBOYADVANCE', 'Banjo Kazooie Grunty''s Revenge (E)(Suxxors)', '2003', 'Platform', 'Rare', '1', 'Platformer', 'Isometric 3D platformer and collection adventure.', 'Stop Gruntilda''s ghost from building a robotic body.', 'A definitive Rareware adventure for the Game Boy Advance.', 'Banjo Kazooie Grunty''s Revenge features a massive world full of secrets. Use Banjo and Kazooie''s iconic moves, transform into different animals, and experience a story set between the first and second console games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie-gruntys-revenge-uvenom', 'GAMEBOYADVANCE', 'Banjo Kazooie Grunty''s Revenge (U)(Venom)', '2003', 'Platform', 'Rare', '1', 'Platformer', 'Isometric 3D platformer and collection adventure.', 'Stop Gruntilda''s ghost from building a robotic body.', 'The classic Banjo adventure for handheld, featuring deep exploration.', 'Banjo Kazooie Grunty''s Revenge (US Version) delivers the perfect mix of platforming and puzzle-solving. Explore five massive worlds, find all the hidden collectibles, and put an end to Grunty''s mechanical plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-kazooie-venganza-de-grunty-sindependent', 'GAMEBOYADVANCE', 'Banjo Kazooie Venganza De Grunty (S)(Independent)', '2003', 'Platform', 'Rare', '1', 'Platformer', 'Isometric 3D platformer and collection adventure.', 'Stop Gruntilda''s ghost from building a robotic body.', 'Spanish-localized edition of the acclaimed Banjo platformer.', 'Banjo Kazooie Venganza De Grunty allows Spanish-speaking fans to enjoy the full story. Master the cooperative moves of the bear and bird to save the Spiral Mountain from the vengeful witch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-pilot-erisingcaravan', 'GAMEBOYADVANCE', 'Banjo Pilot (E)(RisingCaravan)', '2005', 'Racing', 'Rare', '1', 'Arcade Racing', 'Kart racing and aerial flight combat.', 'Win the Jinjo GP and defeat Gruntilda in a race.', 'A high-flying racer featuring the cast of Banjo-Kazooie.', 'Banjo Pilot takes the racing to the skies! Choose from various characters, fly through iconic locations, and use unique items to gain the upper hand in this fast-paced and colorful GBA racing title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('banjo-pilot-uvenom', 'GAMEBOYADVANCE', 'Banjo Pilot (U)(Venom)', '2005', 'Racing', 'Rare', '1', 'Arcade Racing', 'Kart racing and aerial flight combat.', 'Win the Jinjo GP and defeat Gruntilda in a race.', 'A high-flying racer featuring the cast of Banjo-Kazooie.', 'Banjo Pilot (US Version) offers multiple game modes, including Grand Prix and Time Trial. Master the flight mechanics and outmaneuver your rivals in this Rare-developed aerial racing hit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie---12-dancing-princesses-usir-vg', 'GAMEBOYADVANCE', 'Barbie - 12 Dancing Princesses (U)(Sir VG)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Side-scrolling platformer with mini-games.', 'Save the kingdom and find the 12 dancing princesses.', 'Join Barbie on a magical quest filled with dancing and adventure.', 'Barbie: 12 Dancing Princesses features enchanting platforming levels. Use each princess''s unique skills, participate in rhythm-based dance games, and explore the castle to stop the villainous Duchess Rowena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-and-the-magic-of-pegasus-erising-sun', 'GAMEBOYADVANCE', 'Barbie and The Magic of Pegasus (E)(Rising Sun)', '2005', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Side-scrolling adventure with puzzle elements.', 'Break the spell and save the kingdom from the evil Wenlock.', 'A magical journey through the clouds with Barbie and her Pegasus.', 'Barbie and The Magic of Pegasus for GBA lets you play as Princess Annika. Ride Brietta the Pegasus, use the Wand of Light to solve puzzles, and navigate through the icy Kingdom of Clouds in this charming movie-based game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-and-the-magic-of-pegasus-ur18', 'GAMEBOYADVANCE', 'Barbie and The Magic of Pegasus (U)(R18)', '2005', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Side-scrolling adventure with puzzle elements.', 'Break the spell and save the kingdom from the evil Wenlock.', 'A magical journey through the clouds with Barbie and her Pegasus.', 'Barbie and The Magic of Pegasus (US Version) offers a vibrant and accessible adventure. Explore various levels, collect magical items, and complete mini-games to restore peace to the enchanted kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-as-the-island-princess-usir-vg', 'GAMEBOYADVANCE', 'Barbie as the Island Princess (U)(Sir VG)', '2007', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Collection of rhythm and adventure mini-games.', 'Journey to the city and prove you are a true princess.', 'Experience the magic of the tropical island with Barbie.', 'Barbie as the Island Princess for GBA features a variety of engaging mini-games inspired by the movie. Dance, sing, and solve puzzles as Rosella while interacting with her animal friends in this charming handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-as-the-princess-and-the-pauper-erising-sun', 'GAMEBOYADVANCE', 'Barbie as the Princess and the Pauper (E)(Rising Sun)', '2004', 'Adventure', 'WayForward Technologies', '1', 'Adventure', '2D side-scrolling platformer with character swapping.', 'Prove that Erika and Anneliese are the rightful heirs.', 'A royal adventure featuring two princesses and their unique skills.', 'Barbie as the Princess and the Pauper brings the classic tale to GBA. Switch between Anneliese and Erika to solve environmental puzzles, complete platforming challenges, and thwart the villainous Preminger’s plans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-as-the-princess-and-the-pauper-uchameleon', 'GAMEBOYADVANCE', 'Barbie as the Princess and the Pauper (U)(Chameleon)', '2004', 'Adventure', 'WayForward Technologies', '1', 'Adventure', '2D side-scrolling platformer with character swapping.', 'Prove that Erika and Anneliese are the rightful heirs.', 'A royal adventure featuring two princesses and their unique skills.', 'This US version of Princess and the Pauper offers polished 2D platforming action. Explore the village, forest, and castle while using special tools like the Shield or the Book to progress through enchanted levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-groovy-games-epatience', 'GAMEBOYADVANCE', 'Barbie Groovy Games (E)(Patience)', '2003', 'Mini-Games', 'Mass Media', '1', 'Casual', 'Collection of classic board and puzzle games.', 'Win matches and achieve high scores in various casual games.', 'A stylish collection of fun and retro-inspired mini-games.', 'Barbie Groovy Games offers a portable arcade experience. Featuring digital versions of classics like Checkers, Memory, and more, all with a distinct "groovy" aesthetic, it''s perfect for casual gaming on the Game Boy Advance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-groovy-games-ulightforce', 'GAMEBOYADVANCE', 'Barbie Groovy Games (U)(LightForce)', '2003', 'Mini-Games', 'Mass Media', '1', 'Casual', 'Collection of classic board and puzzle games.', 'Win matches and achieve high scores in various casual games.', 'A stylish collection of fun and retro-inspired mini-games.', 'Barbie Groovy Games (US Version) provides endless fun with a variety of puzzle and board games. Customize your experience and play through colorful levels designed for fans of classic casual gaming.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-groovy-games-&-secret-agent-barbie-utrashman', 'GAMEBOYADVANCE', 'Barbie Groovy Games & Secret Agent Barbie (U)(Trashman)', '2003', 'Mini-Games', 'Mass Media', '1', 'Casual', '2-in-1 combo of puzzles and stealth-action platforming.', 'Win arcade games and complete high-stakes spy missions.', 'Two iconic Barbie hits: Groovy Games and Secret Agent in one.', 'This 2-in-1 pack combines the casual fun of Barbie Groovy Games with the exciting stealth missions of Secret Agent Barbie. Solve mysteries globally and enjoy arcade challenges in one comprehensive GBA cartridge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-horse-adventures-esuxxors', 'GAMEBOYADVANCE', 'Barbie Horse Adventures (E)(Suxxors)', '2006', 'Simulation', 'WayForward Technologies', '1', 'Life Simulation', 'Equestrian simulation and trail riding adventure.', 'Rescue the missing horses and win the equestrian championship.', 'Ride and care for your horses in this open-field adventure.', 'Barbie Horse Adventures for GBA lets you explore diverse trails, from forests to deserts. Groom your horse, master jumping obstacles, and complete rescue missions in this relaxing and detailed equestrian simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-horse-adventures-ucezar', 'GAMEBOYADVANCE', 'Barbie Horse Adventures (U)(Cezar)', '2006', 'Simulation', 'WayForward Technologies', '1', 'Life Simulation', 'Equestrian simulation and trail riding adventure.', 'Rescue the missing horses and win the equestrian championship.', 'Ride and care for your horses in this open-field adventure.', 'The US version of Barbie Horse Adventures features immersive riding mechanics. Help Barbie find the runaway horses and train for the big show in a beautiful world filled with nature and exploration.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-in-the-12-dancing-princesses-esir-vg', 'GAMEBOYADVANCE', 'Barbie in the 12 Dancing Princesses (E)(Sir VG)', '2006', 'Adventure', 'WayForward Technologies', '1', 'Adventure', 'Rhythm-based action and side-scrolling platforming.', 'Rescue the King and reunite the twelve dancing sisters.', 'A magical dancing adventure through secret forest realms.', 'Barbie in the 12 Dancing Princesses brings the movie''s magic to your handheld. Use each sister''s unique dancing ability to navigate through platforming levels and solve puzzles to save your father''s kingdom.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-secret-agent-eindependent', 'GAMEBOYADVANCE', 'Barbie Secret Agent (E)(Independent)', '2001', 'Action', 'Runecraft', '1', 'Action Adventure', 'Isometric stealth-action and gadget exploration.', 'Stop the creation of a dangerous chemical and save the world.', 'Go undercover as a secret agent with high-tech gadgets.', 'Barbie Secret Agent for GBA is a surprisingly deep stealth game. Travel to international locations, use spy gear like infrared goggles and decoys, and avoid detection to solve a global fashion industry mystery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barbie-secret-agent-ulightforce', 'GAMEBOYADVANCE', 'Barbie Secret Agent (U)(LightForce)', '2001', 'Action', 'Runecraft', '1', 'Action Adventure', 'Isometric stealth-action and gadget exploration.', 'Stop the creation of a dangerous chemical and save the world.', 'Go undercover as a secret agent with high-tech goggles.', 'This US release of Secret Agent Barbie features diverse mission types. Master stealth-based movement and use clever disguises to infiltrate secret bases in this high-tech handheld spy adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barnyard-erising-sun', 'GAMEBOYADVANCE', 'Barnyard (E)(Rising Sun)', '2006', 'Platform', 'Blue Tongue Entertainment', '1', 'Platformer', 'Open-world adventure with mini-games and exploration.', 'Defend the farm and throw the ultimate barnyard party.', 'Live the life of an animal in this hilarious farm adventure.', 'Barnyard for GBA lets you explore the farm as a customizable cow. Engage in mini-games like bicycle racing and golf, complete quests for your animal friends, and protect the barn from mischievous coyotes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('barnyard-urising-sun', 'GAMEBOYADVANCE', 'Barnyard (U)(Rising Sun)', '2006', 'Platform', 'Blue Tongue Entertainment', '1', 'Platformer', 'Open-world adventure with mini-games and exploration.', 'Defend the farm and throw the ultimate barnyard party.', 'Live the life of an animal in this hilarious farm adventure.', 'The US version of Barnyard captures the humor of the hit movie. Navigate the farm freely, interact with Otis and the gang, and master various challenges to become the ultimate party animal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('baseball-advance-umode7', 'GAMEBOYADVANCE', 'Baseball Advance (U)(Mode7)', '2002', 'Sports', 'Smilebit', '1', 'Baseball', 'Realistic baseball simulation with MLB style.', 'Win the World Series and master the pitching mound.', 'One of the most polished and realistic baseball games on GBA.', 'Baseball Advance sets a high bar for sports on handheld. Featuring deep strategy, smooth animations, and realistic ball physics, it offers a professional baseball experience that is both accessible and challenging for fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bass-tsuri-shiyouze-jmugs', 'GAMEBOYADVANCE', 'Bass Tsuri Shiyouze (J)(Mugs)', '2003', 'Sports', 'Starfish', '1', 'Fishing', 'Fishing simulation with various gear and locations.', 'Catch the rarest fish and win the top fishing tournament.', 'A detailed Japanese fishing sim with realistic water physics.', 'Bass Tsuri Shiyouze offers a comprehensive angling experience on GBA. Choose your lures carefully, find the best fishing spots across various lakes, and master the tension of the line to land the biggest catch.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-begins-utrashman', 'GAMEBOYADVANCE', 'Batman Begins (U)(TrashMan)', '2005', 'Action', 'Griptonite Games', '1', 'Action Adventure', 'Stealth-action and combat-based platforming.', 'Use fear as a weapon to dismantle the criminal underworld.', 'Experience the origin story of the Dark Knight on GBA.', 'Batman Begins brings the cinematic reboot to handheld. Use stealth tactics, smoke pellets, and the environment to strike fear into enemies, mastering the art of the ninja to protect Gotham City from the Scarecrow.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-rise-of-sin-tzu-ueurasia', 'GAMEBOYADVANCE', 'Batman Rise of Sin Tzu (U)(Eurasia)', '2003', 'Action', 'Ubisoft Montreal', '1', 'Action Adventure', 'Side-scrolling beat ''em up and combat action.', 'Defeat Sin Tzu''s army and save Gotham from a new threat.', 'High-octane brawling action with Batman and his allies.', 'Batman: Rise of Sin Tzu for GBA is a classic 2D brawler. Fight through waves of thugs, use the Bat-grapple, and unlock powerful combat moves to defeat a mysterious new villain and his henchmen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-vengeance-erapid-fire', 'GAMEBOYADVANCE', 'Batman Vengeance (E)(Rapid Fire)', '2001', 'Action', 'Bits Studios', '1', 'Action Adventure', '2.5D side-scrolling action and gadget-based combat.', 'Stop the Joker''s latest scheme and restore order to Gotham.', 'A dark and atmospheric Batman adventure based on the TV show.', 'Batman Vengeance features cinematic storytelling and diverse gameplay. Switch between combat, platforming, and gadget-driven puzzles as you hunt down the Joker across the rainy rooftops of Gotham City.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('batman-vengeance-uvenom', 'GAMEBOYADVANCE', 'Batman Vengeance (U)(Venom)', '2001', 'Action', 'Bits Studios', '1', 'Action Adventure', '2.5D side-scrolling action and gadget-based combat.', 'Stop the Joker''s latest scheme and restore order to Gotham.', 'A dark and atmospheric Batman adventure based on the TV show.', 'The US version of Batman Vengeance delivers an immersive superhero experience. Use Batarangs and the Bat-cape to navigate dangerous levels and face off against Gotham''s most iconic villains in stylized boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-b-daman---fire-spirits-urising-sun', 'GAMEBOYADVANCE', 'Battle B-Daman - Fire Spirits (U)(Rising Sun)', '2004', 'Action', 'Takara', '1', 'Action Arena', 'Marble-shooting strategy and robot combat.', 'Customize your B-Daman and win the Fire Spirits tournament.', 'Intense tactical marble battles with deep robot customization.', 'Battle B-Daman - Fire Spirits expands the strategic gameplay of the series. Collect rare parts to build the ultimate marble-shooting robot and compete in high-stakes arena matches against powerful rivals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-b-daman-urising-sun', 'GAMEBOYADVANCE', 'Battle B-Daman (U)(Rising Sun)', '2003', 'Action', 'Takara', '1', 'Action Arena', 'Marble-shooting strategy and robot combat.', 'Win the B-Daman tournament and become the top player.', 'Tactical marble-blasting action based on the popular toy line.', 'Battle B-Daman brings the competitive toy experience to life. Master the physics of your shots, manage your robot''s stats, and climb the ranks of the professional B-Daman circuit on your handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-network-rockman-exe-jeurasia', 'GAMEBOYADVANCE', 'Battle Network RockMan EXE (J)(Eurasia)', '2001', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time combat elements.', 'Stop the World Three organization from destroying the net.', 'The legendary first entry in the Mega Man RPG series.', 'Battle Network RockMan EXE revolutionized the franchise with its grid-based combat. Collect Battle Chips, customize your folder, and navigate the digital world as MegaMan.EXE to solve real-world cybercrimes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-network-rockman-exe-2-jeurasia', 'GAMEBOYADVANCE', 'Battle Network RockMan EXE 2 (J)(Eurasia)', '2002', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time combat elements.', 'Defeat NetMafia Gospel and protect the global network.', 'The high-stakes sequel featuring improved chip mechanics.', 'Battle Network RockMan EXE 2 improves every aspect of the original. Explore a larger digital world, discover new "Styles" for MegaMan, and engage in more complex tactical battles in this definitive GBA RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-network-rockman-exe-3-black-jcezar', 'GAMEBOYADVANCE', 'Battle Network RockMan EXE 3 Black (J)(Cezar)', '2003', 'RPG', 'Capcom', '1', 'Action RPG', 'Grid-based tactical RPG with real-time combat elements.', 'Win the N1 Grand Prix and stop the secret organization WWW.', 'The fan-favorite third entry with a deep customization system.', 'Battle Network RockMan EXE 3 Black offers the most refined combat in the trilogy. Featuring the Navi Customizer and a massive list of chips, it provides an incredible amount of strategic depth for RPG fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battle-x-battle---kyoudai-ou-densetsu-jrising-sun', 'GAMEBOYADVANCE', 'Battle X Battle - Kyoudai Ou Densetsu (J)(Rising Sun)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Tactical monster-collecting RPG and battle system.', 'Become the legendary king by mastering beast battles.', 'A unique Japanese RPG centered on tactical beast combat.', 'Battle X Battle features a deep monster management system. Explore the world, collect powerful creatures, and engage in turn-based strategic battles to prove your dominance in the arena.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlebots---beyond-the-battlebox-epatience', 'GAMEBOYADVANCE', 'BattleBots - Beyond the Battlebox (E)(Patience)', '2002', 'Action', 'Industrial Toys', '1', 'Action Combat', 'Robot combat simulation and arena fighting.', 'Build and program the ultimate robot to win the tournament.', 'Construct your own killer robot and enter the Battlebox.', 'BattleBots - Beyond the Battlebox lets you design a mechanical warrior from scratch. Balance weight, armor, and weaponry to survive intense 1-on-1 arena combat against the world''s most dangerous machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlebots---beyond-the-battlebox-uvenom', 'GAMEBOYADVANCE', 'BattleBots - Beyond the Battlebox (U)(Venom)', '2002', 'Action', 'Industrial Toys', '1', 'Action Combat', 'Robot combat simulation and arena fighting.', 'Build and program the ultimate robot to win the tournament.', 'Construct your own killer robot and enter the Battlebox.', 'The US version of BattleBots offers a robust career mode. Win matches to earn money, upgrade your robot’s motors and saws, and climb the ranks to become the BattleBots champion on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('battlebots---design-and-destroy-urising-sun', 'GAMEBOYADVANCE', 'Battlebots - Design And Destroy (U)(Rising Sun)', '2002', 'Simulation', 'Griptonite Games', '1', 'Simulation', 'Robot design and arena-based combat action.', 'Design, test, and destroy rival robots in the arena.', 'Focus on the engineering and destruction of combat robots.', 'Battlebots - Design And Destroy emphasizes the creative side of robot combat. Experiment with different chassis and weapons, then take your creation into the arena for high-stakes mechanical warfare.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bb-ball-jcaravan', 'GAMEBOYADVANCE', 'BB Ball (J)(Caravan)', '2002', 'Sports', 'Caravan', '2', 'Arcade Sports', 'Top-down arcade sports and ball-based combat.', 'Outscore your opponents in a futuristic ball-game arena.', 'A fast-paced Japanese arcade game featuring ball-based action.', 'BB Ball for GBA is an energetic sports title. Use power-ups and specialized moves to keep the ball in play and defeat your rivals in a variety of colorful, high-speed arena challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beast-shooter---mezase-beast-king-jcezar', 'GAMEBOYADVANCE', 'Beast Shooter - Mezase Beast King (J)(Cezar)', '2003', 'Action', 'Taito', '1', 'Action Shooter', 'Creature-shooting action and collection-based strategy.', 'Defeat the Beast King and collect the ultimate beast souls.', 'A unique Japanese action game featuring monster-based shooting.', 'Beast Shooter for GBA combines fast-paced projectile combat with monster collection. Explore diverse environments, battle wild beasts, and upgrade your gear to become the supreme hunter in this Japanese import.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-friends---dogs-&-cats-usir-vg', 'GAMEBOYADVANCE', 'Best Friends - Dogs & Cats (U)(Sir VG)', '2006', 'Simulation', 'Independent', '1', 'Pet Simulation', 'Virtual pet simulation and care.', 'Raise and train adorable puppies and kittens to be your best friends.', 'A heartwarming pet care simulator for dog and cat lovers.', 'Best Friends - Dogs & Cats for GBA lets you experience the joy of pet ownership. Choose your favorite breed, feed them, play with them, and teach them tricks in this detailed and charming portable virtual pet simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-friends---my-horse-elightforce', 'GAMEBOYADVANCE', 'Best Friends - My Horse (E)(Lightforce)', '2005', 'Simulation', 'Independent', '1', 'Horse Simulation', 'Equestrian simulation and horse management.', 'Care for your horse and win prestigious riding competitions.', 'Manage your own stable and become a champion rider.', 'Best Friends - My Horse offers a comprehensive equestrian experience. From grooming and feeding to mastering jumps and dressage, this GBA title provides a deep simulation for anyone dreaming of owning and competing with their own horse.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('best-play-pro-yakyuu-jchakky', 'GAMEBOYADVANCE', 'Best Play Pro Yakyuu (J)(Chakky)', '2003', 'Sports', 'Ascii', '1', 'Baseball', 'Sports management and baseball simulation.', 'Manage your baseball team to a championship victory.', 'A deep and strategic Japanese baseball management simulator.', 'Best Play Pro Yakyuu focuses on the tactical side of baseball. As a manager, you''ll make crucial decisions on rosters, plays, and strategies to lead your professional team to the top of the Japanese leagues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade---ikuze!-gekitou!-chou-jiryoku-battle!-jindependent', 'GAMEBOYADVANCE', 'Beyblade - Ikuze! Gekitou! Chou Jiryoku Battle! (J)(Independent)', '2003', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Tactical spinning-top combat and simulation.', 'Master magnetic forces to dominate the Beyblade arena.', 'Intense Beyblade battles featuring unique magnetic mechanics.', 'This Japanese Beyblade entry introduces magnetic-based strategy to the GBA. Customize your top, manage its rotation, and use the terrain to knock out rivals in fast-paced, high-stakes spinning-top combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-g-revolution-erising-sun', 'GAMEBOYADVANCE', 'Beyblade G-Revolution (E)(Rising Sun)', '2003', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Action-RPG and tactical spinning-top combat.', 'Win the world championship and stop the BEGA league.', 'Follow the G-Revolution story in this deep Beyblade adventure.', 'Beyblade G-Revolution brings the final season of the original anime to GBA. Experience a story-driven RPG mode, collect hundreds of parts, and engage in real-time arena battles to prove you are the ultimate blader.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-g-revolution-uvenom', 'GAMEBOYADVANCE', 'Beyblade G-Revolution (U)(Venom)', '2003', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Action-RPG and tactical spinning-top combat.', 'Win the world championship and stop the BEGA league.', 'Follow the G-Revolution story in this deep Beyblade adventure.', 'The US version of G-Revolution delivers a robust Beyblade experience. Featuring a wide cast of characters and a deep customization system, it’s the definitive way to experience the high-intensity world of pro blading on handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-vforce---ultimate-blader-jam-erising-sun', 'GAMEBOYADVANCE', 'Beyblade VForce - Ultimate Blader Jam (E)(Rising Sun)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Isometric action and spinning-top combat.', 'Navigate obstacles and defeat bladers in the tournament.', 'A unique isometric take on the Beyblade VForce series.', 'Beyblade VForce - Ultimate Blader Jam challenges your precision and timing. Navigate complex obstacle courses with your Beyblade and engage in arena duels, mastering the physics of the spin to come out on top.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('beyblade-vforce---ultimate-blader-jam-uevasion', 'GAMEBOYADVANCE', 'Beyblade VForce - Ultimate Blader Jam (U)(Evasion)', '2002', 'Action', 'Hudson Soft', '1', 'Action Arena', 'Isometric action and spinning-top combat.', 'Navigate obstacles and defeat bladers in the tournament.', 'A unique isometric take on the Beyblade VForce series.', 'The US version of Ultimate Blader Jam offers challenging level designs and intense rivalries. Use your Bit-Beast powers strategically to clear hazards and defeat the world''s best bladers in this action-packed title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-blocksberg---der-magische-hexenkreis-gsupplex', 'GAMEBOYADVANCE', 'Bibi Blocksberg - Der magische Hexenkreis (G)(Supplex)', '2004', 'Adventure', 'Independent', '1', 'Adventure', 'Adventure and mini-game collection.', 'Join Bibi Blocksberg to break the spell of the magic circle.', 'A magical adventure based on the popular German witch series.', 'Bibi Blocksberg - Der magische Hexenkreis for GBA features a series of magical challenges and puzzles. Use Bibi''s spells to interact with the world, solve environmental mysteries, and complete mini-games in this charming German adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bibi-und-tina---ferien-auf-dem-martinshof-grising-sun', 'GAMEBOYADVANCE', 'Bibi und Tina - Ferien auf dem Martinshof (G)(Rising Sun)', '2004', 'Simulation', 'Independent', '1', 'Life Simulation', 'Social simulation and equestrian adventure.', 'Spend your holidays at Martinshof and complete horse quests.', 'Join Bibi and Tina for a fun-filled vacation with horses.', 'Bibi und Tina - Ferien auf dem Martinshof is a delightful simulation game. Explore the countryside, care for your horses, and participate in riding challenges while following the story of the beloved German duo.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-mutha-truckers-esupplex', 'GAMEBOYADVANCE', 'Big Mutha Truckers (E)(sUppLeX)', '2003', 'Racing', 'Team6 Game Studios', '1', 'Arcade Racing', 'Arcade-style truck driving and mission-based simulation.', 'Earn enough money to pay off the family debt by trucking.', 'High-speed, chaotic truck driving and cargo delivery.', 'Big Mutha Truckers brings the hit console racer to GBA. Choose your character, trade goods across the city, and outrun the law in your massive rig in this humor-filled and fast-paced driving adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('big-mutha-truckers-utrashman', 'GAMEBOYADVANCE', 'Big Mutha Truckers (U)(Trashman)', '2003', 'Racing', 'Team6 Game Studios', '1', 'Arcade Racing', 'Arcade-style truck driving and mission-based simulation.', 'Earn enough money to pay off the family debt by trucking.', 'High-speed, chaotic truck driving and cargo delivery.', 'The US version of Big Mutha Truckers features intense highway racing and trading mechanics. Master the handling of your 18-wheeler to deliver cargo on time and save the family business in this gritty arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle---heroes-erising-sun', 'GAMEBOYADVANCE', 'Bionicle - Heroes (E)(Rising Sun)', '2006', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Isometric run-and-gun shooter.', 'Battle through Voya Nui to defeat the Piraka.', 'Become the ultimate Bionicle hero in this fast-paced shooter.', 'Bionicle Heroes for GBA offers intense action from an isometric perspective. Switch between different Toa forms, each with unique weapons and abilities, to blast through waves of enemies and save the island.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle---heroes-urising-sun', 'GAMEBOYADVANCE', 'Bionicle - Heroes (U)(Rising Sun)', '2006', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Isometric run-and-gun shooter.', 'Battle through Voya Nui to defeat the Piraka.', 'Become the ultimate Bionicle hero in this fast-paced shooter.', 'The US version of Bionicle Heroes brings the epic Lego franchise to life. Collect LEGO studs to upgrade your weapons and master the unique elemental powers of the Toa to defeat the villainous Piraka.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle---maze-of-shadows-eendless-piracy', 'GAMEBOYADVANCE', 'Bionicle - Maze of Shadows (E)(Endless Piracy)', '2005', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Turn-based tactical RPG and exploration.', 'Navigate the Maze of Shadows and stop the Makuta.', 'A deep tactical RPG set in the Bionicle universe.', 'Bionicle - Maze of Shadows is a unique entry in the series. Explore vast underground tunnels, engage in turn-based combat against diverse creatures, and solve puzzles to uncover the secrets of Metru Nui.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle---maze-of-shadows-utrashman', 'GAMEBOYADVANCE', 'Bionicle - Maze of Shadows (U)(Trashman)', '2005', 'Action', 'Traveller''s Tales', '1', 'Action Adventure', 'Turn-based tactical RPG and exploration.', 'Navigate the Maze of Shadows and stop the Makuta.', 'A deep tactical RPG set in the Bionicle universe.', 'The US version of Maze of Shadows offers strategic gameplay for GBA fans. Manage your team of Toa, utilize their elemental strengths in combat, and survive the treacherous depths of the maze.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle-erising-sun', 'GAMEBOYADVANCE', 'Bionicle (E)(Rising Sun)', '2003', 'Action', 'Argonaut Games', '1', 'Action Adventure', 'Isometric action-adventure with combat.', 'Save the island of Mata Nui from the shadows of Makuta.', 'The first epic Bionicle adventure for the Game Boy Advance.', 'Bionicle for GBA lets you play as the six Toa Mata. Each character features unique elemental abilities used to navigate challenging levels and defeat the infected Rahi in this action-packed handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bionicle-uhyperion', 'GAMEBOYADVANCE', 'Bionicle (U)(Hyperion)', '2003', 'Action', 'Argonaut Games', '1', 'Action Adventure', 'Isometric action-adventure with combat.', 'Save the island of Mata Nui from the shadows of Makuta.', 'The first epic Bionicle adventure for the Game Boy Advance.', 'The US version of Bionicle delivers a classic hero''s journey. Master the powers of fire, water, air, earth, stone, and ice to restore peace to the island and fulfill the legend of the Toa.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---boundish-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Boundish (J)(Caravan)', '2006', 'Puzzle', 'Q-Games', '1', 'Abstract Puzzle', 'Modern arcade-style tennis and rhythm.', 'Score points by hitting the ball across stylized neon courts.', 'A minimalist and artistic take on the classic game of Pong.', 'bit Generations - Boundish is part of a unique experimental series. It features clean visuals and diverse game modes that reinterpret paddle-based gameplay into a modern, stylish handheld experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---coloris-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Coloris (J)(Caravan)', '2006', 'Puzzle', 'Q-Games', '1', 'Abstract Puzzle', 'Abstract puzzle and color-matching gameplay.', 'Match colors and clear the board in various artistic modes.', 'A visually stunning and minimalist color-based puzzle game.', 'bit Generations - Coloris focuses on the beauty of color. Change the hue of the blocks to create matches and clear the screen in this relaxing yet challenging puzzle title from the experimental GBA series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---dial-hex-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Dial Hex (J)(Caravan)', '2006', 'Puzzle', 'Q-Games', '1', 'Abstract Puzzle', 'Strategy-puzzle action with hexagonal grids.', 'Rotate and slide hexagons to fill the board and clear levels.', 'A sleek and addictive puzzle game featuring minimalist design.', 'bit Generations - Dial Hex offers a fresh take on the puzzle genre. Manipulate the grid to group colors together, featuring a clean interface and a relaxing soundtrack that defines the bit Generations aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---digidrive-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Digidrive (J)(Caravan)', '2006', 'Racing', 'Q-Games', '1', 'Abstract Racing', 'Rhythm-based strategy and lane management.', 'Navigate the digital lanes to reach the core.', 'A unique blend of rhythm, strategy, and abstract visuals.', 'bit Generations - Digidrive challenges your reflexes and planning. Manage the flow of traffic across digital intersections in this high-energy, minimalist title that focuses on momentum and precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---dotstream-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Dotstream (J)(Caravan)', '2006', 'Shooter', 'Q-Games', '1', 'Music Shooter', 'High-speed abstract racing and rhythm.', 'Race across colorful digital streams and avoid obstacles.', 'A stylish and minimalist racing game with a heavy focus on sound.', 'bit Generations - Dotstream turns racing into an artistic experience. Guide your line through complex courses, managing speed and energy while enjoying a reactive electronic soundtrack on your GBA.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---orbital-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Orbital (J)(Caravan)', '2006', 'Strategy', 'Q-Games', '1', 'Abstract Strategy', 'Abstract orbital physics and puzzle-platforming.', 'Navigate your craft through various orbits to reach the goal.', 'A unique game centered on the physics of gravity and orbit.', 'bit Generations - Orbital is a minimalist title where you control a small craft using gravitational pull. Master the physics of space to navigate through complex stages in this calm and intellectual handheld game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bit-generations---soundvoyager-jcaravan', 'GAMEBOYADVANCE', 'Bit Generations - Soundvoyager (J)(Caravan)', '2006', 'Music', 'Q-Games', '1', 'Music Exploration', 'Audio-only experimental rhythm and exploration.', 'Use sound cues to navigate and find hidden audio signals.', 'A groundbreaking game that can be played with sound alone.', 'bit Generations - Soundvoyager is an experimental masterpiece. Designed to be played using only stereo audio cues, it offers a series of mini-games that challenge your spatial hearing and rhythm in a way no other GBA game does.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-belt-challenge-evenom', 'GAMEBOYADVANCE', 'Black Belt Challenge (E)(Venom)', '2002', 'Sports', 'Unique Development Studios', '2', 'Martial Arts', '2D fighting game with various characters.', 'Defeat all challengers to win the Black Belt tournament.', 'A classic handheld brawler with a variety of martial arts styles.', 'Black Belt Challenge for GBA features traditional 1-on-1 fighting action. Choose from a diverse roster of fighters, master their special moves, and climb the ranks of the professional circuit in this portable fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-black-jnobody', 'GAMEBOYADVANCE', 'Black Black (J)(Nobody)', '2002', 'Puzzle', 'Unknown', '1', 'Puzzle', 'Dark fantasy RPG and adventure.', 'Navigate a dark world and survive against powerful foes.', 'A mysterious and atmospheric Japanese RPG for GBA.', 'Black Black offers a deep role-playing experience with a focus on atmosphere and story. Explore a beautifully detailed 2D world, manage your party, and engage in tactical combat in this Japanese import.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('black-matrix-zero-jcezar', 'GAMEBOYADVANCE', 'Black Matrix Zero (J)(Cezar)', '2002', 'RPG', 'Flight-Plan', '1', 'Tactical RPG', 'Tactical turn-based RPG with grid combat.', 'Lead your rebellion and master the power of the wings.', 'A high-quality tactical RPG with a deep branching storyline.', 'Black Matrix Zero for GBA is a prequel to the cult classic series. Featuring deep character customization and complex grid-based battles, it offers a mature story and a unique dark fantasy setting for strategy fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackthorne-eendless-piracy', 'GAMEBOYADVANCE', 'Blackthorne (E)(Endless Piracy)', '1994', 'Action', 'Blizzard Entertainment', '1', 'Action Platformer', 'Cinematic platformer with combat and puzzles.', 'Reclaim your throne and defeat the Sarlac''s minions.', 'A dark and gritty sci-fi adventure from the creators of Diablo.', 'Blackthorne brings the 16-bit classic to GBA. As Kyle Vlaros, use your shotgun and tactical positioning to clear levels, solve environmental puzzles, and survive the brutal alien world of Tuul in this cinematic action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blackthorne-umode7', 'GAMEBOYADVANCE', 'Blackthorne (U)(Mode7)', '1994', 'Action', 'Blizzard Entertainment', '1', 'Action Platformer', 'Cinematic platformer with combat and puzzles.', 'Reclaim your throne and defeat the Sarlac''s minions.', 'A dark and gritty sci-fi adventure from the creators of Diablo.', 'The US version of Blackthorne features the same intense, strategic gunplay. Master the cover mechanics and explore the sprawling alien landscapes to avenge your father and reclaim your destiny in this Blizzard classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blades-of-thunder-utrashman', 'GAMEBOYADVANCE', 'Blades of Thunder (U)(TrashMan)', '2004', 'Action', 'Kemco', '1', 'Action Shooter', 'Combat flight simulation and aerial dogfighting.', 'Complete high-stakes missions and eliminate enemy aircraft.', 'High-octane helicopter and jet combat for military fans.', 'Blades of Thunder for GBA delivers intense aerial warfare. Pilot a variety of attack helicopters and fighter jets across diverse mission types, featuring impressive sprite-scaling graphics and fast-paced arcade action that pushes your reflexes to the limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bleach-advance-jcaravan', 'GAMEBOYADVANCE', 'Bleach Advance (J)(Caravan)', '2003', 'Action', 'DreamFactory', '1', 'Action Fighting', '2D fighting game with special spirit attacks.', 'Fight through the Gotei 13 and master your Bankai.', 'The first GBA fighting game based on the hit Bleach anime.', 'Bleach Advance brings the early arcs of the series to life. Choose from fan-favorite characters like Ichigo and Rukia, mastering their unique spiritual powers and flash-steps in fast-paced 1-on-1 battles that capture the show''s high-energy spirit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('blender-bros-umode7', 'GAMEBOYADVANCE', 'Blender Bros. (U)(Mode7)', '2002', 'Platform', 'Hudson Soft', '2', 'Platformer', 'Side-scrolling platformer and action adventure.', 'Save the galaxy from the villainous Zoolians.', 'A fast-paced and colorful platformer with a unique sonic twist.', 'Blender Bros. features fluid movement and clever level design. Use your long ears to glide, spin, and defeat enemies across various planets, offering a polished 2D adventure that fans of classic platformers will love for its charm and challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bmx-trick-racer-umode7', 'GAMEBOYADVANCE', 'BMX Trick Racer (U)(Mode7)', '2003', 'Racing', 'Trickstar Games', '1', 'Arcade Racing', 'Extreme sports BMX racing and stunt action.', 'Master bike tricks and win the world BMX championship.', 'Perform death-defying stunts and race for the gold.', 'BMX Trick Racer focuses on technical skill and timing. Navigate complex courses, perform grinds and backflips to earn points, and upgrade your bike to become the ultimate freestyle champion in this portable extreme sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('board-game-classics-eindependent', 'GAMEBOYADVANCE', 'Board Game Classics (E)(Independent)', '2003', 'Board', 'Mass Media', '4', 'Board Game', 'Collection of classic tabletop board games.', 'Outsmart opponents in Checkers, Chess, and Backgammon.', 'A portable digital library of the world''s favorite board games.', 'Board Game Classics for GBA offers a convenient way to play timeless games like Chess and Checkers on the go. Featuring adjustable AI difficulty and faithful rule sets, it’s the perfect companion for casual gamers who enjoy strategic puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('board-game-classics-utrashman', 'GAMEBOYADVANCE', 'Board Game Classics (U)(Trashman)', '2003', 'Board', 'Mass Media', '4', 'Board Game', 'Collection of classic tabletop board games.', 'Outsmart opponents in Checkers, Chess, and Backgammon.', 'A portable digital library of the world''s favorite board games.', 'Board Game Classics (US Version) provides a clean interface and smooth gameplay for multiple tabletop staples. Test your wits against the computer or a friend in this comprehensive collection of traditional strategy games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bobobohbo-bohbobo-ougi-875-bakuretsu-hanage-shinken-jpolla', 'GAMEBOYADVANCE', 'Bobobohbo Bohbobo Ougi 87.5 Bakuretsu Hanage Shinken (J)(Polla)', '2004', 'Action', 'Takara', '1', 'Action Comedy', 'Turn-based RPG and mini-game adventure.', 'Use the Fist of the Nose Hair to defeat the Chrome Dome Empire.', 'A bizarre and hilarious RPG based on the surreal Bobobo anime.', 'Bobobohbo Bohbobo Ougi 87.5 is a treat for fans of Japanese humor. Engage in turn-based battles featuring the most ridiculous attacks imaginable, following the surreal story of Bobobo-bo Bo-bobo in his quest to protect everyone''s hair.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boboboubo-boubobo---9-kiwame-senshi-gyagu-yuugou-jrising-sun', 'GAMEBOYADVANCE', 'Boboboubo Boubobo - 9 Kiwame Senshi Gyagu Yuugou (J)(Rising Sun)', '2005', 'Action', 'Takara', '1', 'Action Comedy', 'Multi-genre adventure and mini-game collection.', 'Assemble the nine warriors to stop the hair-hunters.', 'A wacky mashup of mini-games and bizarre comedy.', '9 Kiwame Senshi Gyagu Yuugou brings the chaotic energy of the Bobobo universe to GBA. Solve puzzles, complete crazy mini-games, and interact with the show''s strange cast of characters in this unique and colorful Japanese title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boboboubo-boubobo---bakuten-hajike-taisen-jcaravan', 'GAMEBOYADVANCE', 'Boboboubo Boubobo - Bakuten Hajike Taisen (J)(Caravan)', '2004', 'Action', 'Takara', '1', 'Action Comedy', 'Grid-based tactical strategy and combat.', 'Defeat the enemy forces using bizarre nose-hair techniques.', 'A strategic take on the Bobobo series with tactical depth.', 'Bakuten Hajike Taisen offers a deeper tactical experience compared to other entries. Manage your team of weird warriors on a grid, utilizing surreal special moves to clear the board in this engaging and funny strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boboboubo-boubobo-2-jcezar', 'GAMEBOYADVANCE', 'Boboboubo Boubobo 2 (J)(Cezar)', '2005', 'Action', 'Takara', '1', 'Action Comedy', 'Turn-based RPG and adventure.', 'Continue the journey to save hair and stop the empire.', 'The high-energy sequel to the surreal Bobobo RPG series.', 'Boboboubo Boubobo 2 expands on the bizarre combat and storytelling of the original. Featuring more characters, evolved battle mechanics, and even weirder jokes, it is the definitive handheld experience for fans of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boktai---the-sun-is-in-your-hand-erising-sun', 'GAMEBOYADVANCE', 'Boktai - The Sun is in your Hand (E)(Rising Sun)', '2003', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'A groundbreaking vampire-hunting RPG from Hideo Kojima.', 'Boktai: The Sun is in Your Hand is a unique GBA masterpiece. Utilizing a real-life light sensor on the cartridge, players must use actual sunlight to charge their Solar Gun and defeat the undead in this atmospheric stealth-adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boktai---the-sun-is-in-your-hand-ueurasia', 'GAMEBOYADVANCE', 'Boktai - The Sun is in Your Hand (U)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'A groundbreaking vampire-hunting RPG from Hideo Kojima.', 'The US version of Boktai features the same innovative sunlight mechanics. Master stealth, solve intricate environmental puzzles, and experience a dark, compelling story that changes based on the time of day and the intensity of the sun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boktai-2---solar-boy-django-eeternity', 'GAMEBOYADVANCE', 'Boktai 2 - Solar Boy Django (E)(Eternity)', '2004', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric action-adventure and RPG with combat.', 'Defeat the Dark Boy and restore light to the world.', 'The epic sequel to the solar-powered vampire hunting saga.', 'Boktai 2: Solar Boy Django introduces new weapons and the ability to forge gear. While still utilizing the solar sensor, this entry focuses more on traditional RPG elements and melee combat, offering a deeper and more versatile gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boktai-2---solar-boy-django-urising-sun', 'GAMEBOYADVANCE', 'Boktai 2 - Solar Boy Django (U)(Rising Sun)', '2004', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric action-adventure and RPG with combat.', 'Defeat the Dark Boy and restore light to the world.', 'The epic sequel to the solar-powered vampire hunting saga.', 'Boktai 2 (US Version) continues Django''s journey. Use the solar sensor to charge your weapons and solve puzzles, exploring vast dungeons and battling giant bosses in one of the most technically impressive games on the platform.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-no-kuwagata-3-jrising-sun', 'GAMEBOYADVANCE', 'Boku No Kuwagata 3 (J)(Rising Sun)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Insect Simulation', 'Beetle breeding and tactical battle simulation.', 'Breed and train the ultimate stag beetle for battle.', 'A deep and charming Japanese beetle-collecting simulation.', 'Boku No Kuwagata 3 lets you experience the life of a beetle trainer. Explore the countryside to find rare specimens, manage their diet and training, and compete in strength-based tournaments in this detailed Japanese hobby sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boku-wa-koukuu-kanseikan-jrapid-fire', 'GAMEBOYADVANCE', 'Boku wa Koukuu Kanseikan (J)(Rapid Fire)', '2003', 'Simulation', 'Spike', '1', 'Simulation', 'Air traffic control simulation and management.', 'Manage flight paths and ensure safe landings and takeoffs.', 'A realistic and challenging Japanese air traffic control sim.', 'Boku wa Koukuu Kanseikan puts you in the control tower of a busy airport. Balance arrival and departure schedules, manage taxiing planes, and prevent collisions in this high-pressure, strategic simulation title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---mineral-town-for-girls-jcezar', 'GAMEBOYADVANCE', 'Bokujou Monogatari - Mineral Town for Girls (J)(Cezar)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and social RPG.', 'Manage a successful farm and find love in Mineral Town.', 'The female-protagonist version of the classic Harvest Moon title.', 'Mineral Town for Girls (Harvest Moon: More Friends of Mineral Town) offers a deep farming experience. Grow crops, raise livestock, and build relationships with the townspeople from a new perspective in this beloved life-sim.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokujou-monogatari---mineral-town-no-nakama-tachi-jmegaroms', 'GAMEBOYADVANCE', 'Bokujou Monogatari - Mineral Town no Nakama Tachi (J)(Megaroms)', '2003', 'Simulation', 'Marvelous Interactive', '1', 'Farming Simulation', 'Farming simulation and social RPG.', 'Restore your grandfather''s farm to its former glory.', 'The legendary GBA entry in the Harvest Moon farming series.', 'Mineral Town no Nakama Tachi is the definitive farming simulation. Experience the changing seasons, participate in town festivals, and build a lasting legacy in this addictive and heartwarming RPG that defined the genre on handheld.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bokura-no-taiyo-jeurasia', 'GAMEBOYADVANCE', 'Bokura no Taiyo (J)(Eurasia)', '2003', 'Action', 'Konami', '1', 'Action Adventure', 'Isometric action-adventure with a real-time solar sensor.', 'Use the power of the sun to purify vampires and monsters.', 'The original Japanese release of the innovative solar RPG.', 'Bokura no Taiyo features the same groundbreaking sunlight-based gameplay. Master the "Gun Del Sol" and navigate complex dungeons filled with traps and undead foes in this Hideo Kojima-produced classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-jetters-english', 'GAMEBOYADVANCE', 'Bomberman Jetters (English)', '2002', 'Action', 'Hudson Soft', '4', 'Action Platformer', 'Top-down action-adventure and puzzle-solving.', 'Stop the Mujoe and the Hige Hige Bandits.', 'A fan-translated adventure featuring classic Bomberman action.', 'Bomberman Jetters (English Patch) brings the anime-inspired story to western fans. Explore diverse planets, use unique "Charaboms" to gain abilities, and solve environmental puzzles in this expansive single-player adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-jetters-jeurasia', 'GAMEBOYADVANCE', 'Bomberman Jetters (J)(Eurasia)', '2002', 'Action', 'Hudson Soft', '4', 'Action Platformer', 'Top-down action-adventure and puzzle-solving.', 'Stop the Mujoe and the Hige Hige Bandits.', 'The original Japanese release based on the Jetters anime.', 'Bomberman Jetters for GBA blends classic bomb-dropping gameplay with a deep adventure mode. Travel through various stages, collecting power-ups and battling massive bosses in a vibrant, cartoon-style world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-jetters-game-collection-jeurasia', 'GAMEBOYADVANCE', 'Bomberman Jetters Game Collection (J)(Eurasia)', '2003', 'Action', 'Hudson Soft', '4', 'Action Platformer', 'Collection of Bomberman mini-games.', 'Master various arcade challenges and high-score puzzles.', 'A fun-filled collection of Bomberman-themed mini-games.', 'Bomberman Jetters Game Collection offers a variety of quick-play challenges. From racing to logic puzzles, this Japanese title is perfect for short sessions, featuring the charming cast of the Jetters series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2---bomberman-version-jhyperion', 'GAMEBOYADVANCE', 'Bomberman Max 2 - Bomberman Version (J)(Hyperion)', '2002', 'Action', 'Hudson Soft', '1', 'Action Maze', 'Top-down action and creature collection RPG.', 'Defeat the Brain Bomber and stop the shrinking of Earth.', 'A unique Bomberman adventure focusing on the hero himself.', 'Bomberman Max 2 - Bomberman Version allows you to raise and evolve Charaboms to help you in battle. Clear classic bomb-laying stages while navigating a branching world map in this creature-collecting hybrid.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2---max-version-jhyperion', 'GAMEBOYADVANCE', 'Bomberman Max 2 - Max Version (J)(Hyperion)', '2002', 'Action', 'Hudson Soft', '1', 'Action Maze', 'Top-down action and creature collection RPG.', 'Defeat the Brain Bomber and stop the shrinking of Earth.', 'Play as the rival Max in this companion Bomberman title.', 'Bomberman Max 2 - Max Version offers a different perspective on the story. While the core gameplay remains the same, players use Max''s unique skills and different Charaboms to clear stages and defeat the villainous bandits.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2-blue-emegaroms', 'GAMEBOYADVANCE', 'Bomberman Max 2 Blue (E)(Megaroms)', '2003', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The European release of the creature-collecting Bomberman hit.', 'Bomberman Max 2 Blue features over 80 Charaboms to collect and train. Navigate through grid-based levels, use strategic bomb placement, and trade creatures with the Red version to complete your collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2-blue-advance-umode7', 'GAMEBOYADVANCE', 'Bomberman Max 2 Blue Advance (U)(Mode7)', '2003', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The US release of the Blue version featuring Charabom training.', 'Bomberman Max 2 Blue Advance delivers a deep single-player campaign and competitive multiplayer. Master the elemental powers of your Charaboms to overcome obstacles and solve puzzles in this expansive bomb-dropping RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2-red-emegaroms', 'GAMEBOYADVANCE', 'Bomberman Max 2 Red (E)(Megaroms)', '2003', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The companion Red version with exclusive Charaboms.', 'Bomberman Max 2 Red features a different set of collectable creatures compared to Blue. Players must navigate challenging stages and use their tactical skills to stop the shrinking of their home planet.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-max-2-red-advance-umode7', 'GAMEBOYADVANCE', 'Bomberman Max 2 Red Advance (U)(Mode7)', '2003', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Top-down action and creature collection RPG.', 'Rescue the Charaboms and defeat the shadow organization.', 'The US release of the Red version featuring Charabom training.', 'Bomberman Max 2 Red Advance is the perfect strategic action game. Level up your creatures, find hidden power-ups, and enjoy classic Bomberman battle modes in this content-rich handheld title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-story-jeurasia', 'GAMEBOYADVANCE', 'Bomberman Story (J)(Eurasia)', '2000', 'Action', 'Hudson Soft', '4', 'Action Maze', 'Action-RPG with exploration and turn-based battles.', 'Embark on a quest to save the world and find the missing bombs.', 'A deep and story-driven RPG take on the Bomberman franchise.', 'Bomberman Story (Japanese Version) focuses on exploration and character interaction. Unlike traditional entries, it features an overhead world map, towns, and a quest system, blending the bomb-dropping action with classic RPG elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bomberman-tournament-umode7', 'GAMEBOYADVANCE', 'Bomberman Tournament (U)(Mode7)', '2001', 'Action', 'Hudson Soft', '4', 'Action Adventure', 'Action-RPG and tactical combat.', 'Defeat the shadows and win the Bomberman tournament.', 'The localized RPG adventure for the Western market.', 'Bomberman Tournament is a standout title on GBA. Explore a Zelda-like world, collect and battle creatures in a tactical mini-game, and clear dungeons using traditional Bomberman mechanics in this highly polished adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bookworm-urising-sun', 'GAMEBOYADVANCE', 'BookWorm (U)(Rising Sun)', '2003', 'Puzzle', 'PopCap Games', '1', 'Word Puzzle', 'Word-building puzzle gameplay.', 'Feed the hungry bookworm by linking letters to form words.', 'A classic and addictive word puzzle game for all ages.', 'BookWorm for GBA brings the hit PC puzzle game to handheld. Help Lex the Bookworm devour letters to create words and clear the board, featuring various game modes that test your vocabulary and speed in a fun, educational environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-yuuki-densetsu-plaston-gate-jrising-sun', 'GAMEBOYADVANCE', 'Bouken Yuuki Densetsu Plaston Gate (J)(Rising Sun)', '2003', 'Action', 'Takara', '1', 'Action Adventure', 'Creature-collecting RPG and tactical combat.', 'Explore the world of Plust Gate and master your Plaston.', 'A unique Japanese adventure featuring monster collection and battles.', 'Bouken Yuuki Densetsu Plaston Gate offers a deep RPG experience. Travel across vibrant lands, collect mysterious creatures known as Plastons, and engage in strategic turn-based battles to uncover the secrets of the ancient Gate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-yuuki-plastar-world---densetsu-no-plust-gate-ex-jindependent', 'GAMEBOYADVANCE', 'Bouken Yuuki PlaStar World - Densetsu no Plust Gate EX (J)(Independent)', '2004', 'Action', 'Takara', '1', 'Action Adventure', 'Enhanced creature-collecting RPG.', 'Complete the ultimate collection and save the Plust world.', 'An expanded version of the Japanese monster-battle adventure.', 'Densetsu no Plust Gate EX features new creatures, refined battle mechanics, and additional story content. Master the elemental strengths of your Plastons to become the supreme trainer in this high-quality Japanese GBA import.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-yuuki-plaston-gp-jrising-sun', 'GAMEBOYADVANCE', 'Bouken Yuuki Plaston GP (J)(Rising Sun)', '2003', 'Racing', 'Takara', '1', 'Arcade Racing', 'Racing and vehicular combat with creature elements.', 'Win the Plaston GP tournament using unique monster-cars.', 'A high-speed Japanese racer featuring creature-inspired vehicles.', 'Bouken Yuuki Plaston GP combines the thrill of racing with creature combat. Customize your Plaston vehicle, use special abilities to outmaneuver rivals, and master diverse tracks to claim the championship trophy.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bouken-ou-beet---busters-road-jcaravan', 'GAMEBOYADVANCE', 'Bouken-Ou Beet - Busters Road (J)(Caravan)', '2002', 'Action', 'Bandai', '1', 'Action Adventure', 'Action-adventure and monster-hunting RPG.', 'Defeat the Vandel monsters and become a top-tier Buster.', 'Based on the popular manga series, embark on a quest for glory.', 'Bouken-Ou Beet - Busters Road brings the world of Beet the Vandel Buster to GBA. Engage in real-time combat, upgrade your "Saiga" weapons, and complete dangerous missions to cleanse the world of dark forces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boukyaku-no-senritsu-jindependent', 'GAMEBOYADVANCE', 'Boukyaku no Senritsu (J)(Independent)', '2003', 'Adventure', 'Independent', '1', 'Adventure', 'Strategy and adventure with mecha elements.', 'Pilot the Icarus and defeat the monsters threatening humanity.', 'A dark and stylish Japanese adventure based on the cult anime.', 'Boukyaku no Senritsu (The Melody of Oblivion) offers a unique blend of narrative exploration and strategic combat. Battle through surreal landscapes and master the powers of the Melody to fulfill your destiny in this atmospheric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boulder-dash-ex-epatience', 'GAMEBOYADVANCE', 'Boulder Dash EX (E)(Patience)', '2002', 'Puzzle', 'First Star Software', '1', 'Action Puzzle', 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'A modern remake of the legendary arcade classic Boulder Dash.', 'Boulder Dash EX revitalizes the retro hit with updated graphics and new gameplay modes. Navigate treacherous underground caves, outsmart enemies, and manage physics-based puzzles to collect every gem and escape alive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boulder-dash-ex-jpolla', 'GAMEBOYADVANCE', 'Boulder Dash EX (J)(Polla)', '2002', 'Puzzle', 'First Star Software', '1', 'Action Puzzle', 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'The Japanese edition of the updated arcade puzzle classic.', 'Boulder Dash EX (Japanese Version) delivers the same addictive grid-based strategy. Experience the classic puzzle levels and the new world-based adventure mode, perfect for fans of logic and timing-based gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boulder-dash-ex-umode7', 'GAMEBOYADVANCE', 'Boulder Dash EX (U)(Mode7)', '2002', 'Puzzle', 'First Star Software', '1', 'Action Puzzle', 'Classic puzzle-action and cave exploration.', 'Collect diamonds and find the exit while avoiding falling rocks.', 'A modern remake of the legendary arcade classic Boulder Dash.', 'Boulder Dash EX for GBA offers 2D puzzle-solving at its best. Featuring the classic "Dig-and-Drop" mechanics, players must navigate dangerous mines and use falling boulders to trap enemies and uncover hidden paths.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bowser-smk', 'GAMEBOYADVANCE', 'Bowser (SMK)', '1994', 'Hack', 'Nintendo', '1', 'ROM Hack', 'High-speed kart racing and battle.', 'Use Bowser''s power to dominate the race track.', 'A special fan-made mod featuring Bowser in the classic racer.', 'Bowser (SMK) is a creative GBA adaptation that lets you take control of the Koopa King. Experience high-velocity racing and classic battle modes with a focus on Bowser''s unique heavy-weight driving style.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('boxing-fever-ulightforce', 'GAMEBOYADVANCE', 'Boxing Fever (U)(Lightforce)', '2001', 'Sports', 'Kemco', '1', 'Boxing', 'First-person perspective arcade boxing.', 'Knock out all opponents to become the boxing champion.', 'A fast-paced and stylish boxing game with a 1st-person view.', 'Boxing Fever delivers intense ring action on the GBA. Using an immersive first-person camera, players must time their jabs, hooks, and dodges perfectly to climb the ranks and defeat the world''s toughest heavyweights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---forever-diamondz-esir-vg', 'GAMEBOYADVANCE', 'Bratz - Forever Diamondz (E)(Sir VG)', '2006', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and fashion simulation with mini-games.', 'Search for the ultimate fashion diamond across the country.', 'Join the Bratz girls on a stylish cross-country road trip.', 'Bratz - Forever Diamondz features exploration, fashion design, and music-themed mini-games. Travel to different cities, enter fashion shows, and style the girls with the latest accessories in this vibrant handheld adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---forever-diamondz-grising-sun', 'GAMEBOYADVANCE', 'Bratz - Forever Diamondz (G)(Rising Sun)', '2006', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and fashion simulation with mini-games.', 'Search for the ultimate fashion diamond across the country.', 'German-localized edition of the stylish Bratz road trip.', 'Forever Diamondz (German Version) brings the Bratz fashion world to life. Help Cloé, Sasha, Jade, and Yasmin find the next big trend while engaging in fun activities and managing the girls'' social lives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---forever-diamondz-usir-vg', 'GAMEBOYADVANCE', 'Bratz - Forever Diamondz (U)(Sir VG)', '2006', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and fashion simulation with mini-games.', 'Search for the ultimate fashion diamond across the country.', 'Join the Bratz girls on a stylish cross-country road trip.', 'Bratz - Forever Diamondz for GBA captures the spirit of the dolls. Navigate urban environments, customize outfits, and participate in dance and fashion competitions to prove the Bratz are the best in the business.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---rock-angelz-findependent', 'GAMEBOYADVANCE', 'Bratz - Rock Angelz (F)(Independent)', '2005', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and rhythm-based action.', 'Start your own fashion magazine and rock the world.', 'The French version of the Bratz rock star adventure.', 'Bratz - Rock Angelz (French Version) allows players to travel to London and Paris. Manage your own magazine, dress the girls in iconic rock outfits, and perform on stage in this multi-faceted social simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('bratz---rock-angelz-sindependent', 'GAMEBOYADVANCE', 'Bratz - Rock Angelz (S)(Independent)', '2005', 'Adventure', 'Altron', '1', 'Adventure', 'Adventure and rhythm-based action.', 'Start your own fashion magazine and rock the world.', 'The Spanish version of the Bratz rock star adventure.', 'Bratz - Rock Angelz (Spanish Version) features the journey of the girls as they form their own band. Solve mysteries, explore fashion capitals, and participate in photography and design mini-games.');